export const CHAPTERS=[{"act": "ACTE I", "season": "HIVER 1890", "title": "L'Apprenti", "text": "January to March. The Russian influenza has half of Paris in bed, the crowds of the Exposition have gone home, and Monsieur Eiffel's tower still stands over the Champ de Mars like an unanswered question. In a workshop on the rue Mouffetard every clock has stopped at a quarter past two, and the finest regulator in France is gone."}, {"act": "ACTE II", "season": "PRINTEMPS 1890", "title": "Le Salon", "text": "March to May. The Indépendants hang Monsieur Seurat's dots on the Champs-Élysées, the Salon splits in two, the workers of Paris march on the first of May for the eight-hour day, and someone in Paris is copying everything."}, {"act": "ACTE III", "season": "ÉTÉ 1890", "title": "La Fête", "text": "June to August. The tower is lit for the Fourteenth of July, they dance the quadrille at the new Moulin Rouge, and twelve clocks across the city are quietly being tuned to one chord."}, {"act": "ACTE IV", "season": "AUTOMNE 1890", "title": "Les Contes", "text": "September to November. Massenet's sorceress at the Châtelet, Sarah Bernhardt as Cleopatra at the Porte Saint-Martin, a petrol carriage from the Panhard works coughing down the boulevards, and the Baron makes his offer."}, {"act": "ACTE V", "season": "DÉCEMBRE 1890", "title": "Réveillon", "text": "December. The coldest winter in living memory sets in, and the Seine begins to freeze. One gala night at the Opéra, and twelve clocks that will strike midnight twelve seconds early."}];
export const DRAMATIS=[{"name": "Théo Marchal", "role": "Protagonist. A watchmaker's apprentice, 19, from the rue Mouffetard. Quick hands, a good ear, and a debt he did not choose.", "real": false}, {"name": "Maître Augustin Vallet", "role": "Théo's master, a horologist of genius. His masterpiece, a tourbillon regulator, is stolen in the first scene.", "real": false}, {"name": "Henri Vautrin", "role": "A penniless painter at the rue Ravignan piano works. Théo's oldest friend; knows every studio, model and cabaret in Montmartre.", "real": false}, {"name": "Maza", "role": "Fence and fixer of Les Halles, holding court at Au Chien qui Fume. Buys anything, sells everything, keeps her word.", "real": false}, {"name": "Lucie Arnoux", "role": "Printer, engraver and reformed forger, back from hiding in Geneva. Can copy any signature, refuses to copy a conscience.", "real": false}, {"name": "Baron Léopold Vaneau", "role": "VILLAIN. Financier, collector, patron of the Opéra, early investor in petrol carriages. Behind the velvet: a ring of thieves, forgers and bribed officials.", "real": false}, {"name": "Silas Crane", "role": "VILLAIN. Vaneau's English forger and cracksman. Paints like an angel, lies like a ledger.", "real": false}, {"name": "Inspecteur Gaspard Mourier", "role": "VILLAIN. A Préfecture detective on Vaneau's payroll who hunts Théo through all five acts.", "real": false}, {"name": "La Pie (Odile Vaneau)", "role": "The Magpie: a masked cat-burglar working for the Baron. His ward, and not as loyal as he believes.", "real": false}, {"name": "Jules Broca", "role": "A bell-founder and old Communard, home from New Caledonia since the amnesty of 1880, now a porter at the Gare de Lyon (fictional). Tunes the counter-chord.", "real": false}, {"name": "Moineau", "role": "A Montmartre street urchin (fictional), La Pie's lookout; spared or sold in Act I.", "real": false}, {"name": "Paul Signac", "role": "Painter, 26; a moving spirit of the Société des Artistes Indépendants, whose sixth exhibition opens on 20 March 1890.", "real": true}, {"name": "Georges Seurat", "role": "Painter, 30; the quiet inventor of the pointillist method. Shows Le Chahut and Jeune femme se poudrant at the Indépendants in 1890.", "real": true}, {"name": "Edgar Degas", "role": "Painter, 55. Long since done with group exhibitions; dry wit, sharp eye, little patience for fools.", "real": true}, {"name": "Mary Cassatt", "role": "Painter; in April 1890 she is enthralled by the great exhibition of Japanese prints at the École des Beaux-Arts. Practical, generous, and the first to believe Théo.", "real": true}, {"name": "Berthe Morisot", "role": "Painter; her house on the rue de Villejust near the Étoile is a refuge of good sense.", "real": true}, {"name": "Gustave Caillebotte", "role": "Painter, collector and boat-builder, living at Petit-Gennevilliers; quiet benefactor of his friends.", "real": true}, {"name": "Camille Pissarro", "role": "Painter, 60, in from Éragny; a patient mentor to younger artists.", "real": true}, {"name": "Claude Monet", "role": "Painter, settled at Giverny and painting the haystacks; in 1890 he raises a public subscription to buy Manet's Olympia for the nation.", "real": true}, {"name": "Pierre-Auguste Renoir", "role": "Painter, living in Montmartre.", "real": true}, {"name": "Theo van Gogh", "role": "Dealer, 33; manager of Boussod, Valadon et Cie on the boulevard Montmartre, who keeps the new painting on his mezzanine.", "real": true}, {"name": "Paul Durand-Ruel", "role": "Art dealer, rue Laffitte and rue Le Peletier; staking his fortune on the Impressionists in Paris and New York.", "real": true}, {"name": "Julien 'Père' Tanguy", "role": "Colour merchant of rue Clauzel; extends credit to painters in paint, and in kindness.", "real": true}, {"name": "Henri de Toulouse-Lautrec", "role": "Painter, 25; draws the dancers of the Moulin Rouge and the riders of the Cirque Fernando.", "real": true}, {"name": "Émile Zola", "role": "Novelist; La Bête humaine appears in March 1890. An observer who notices everything.", "real": true}, {"name": "Guy de Maupassant", "role": "Writer; Notre Cœur is serialised in 1890.", "real": true}, {"name": "Stéphane Mallarmé", "role": "Poet; his Tuesday evenings on the rue de Rome.", "real": true}, {"name": "Georges Clemenceau", "role": "Deputy for the Var, editor of La Justice, former mayor of Montmartre; lives on the rue Franklin in Passy.", "real": true}, {"name": "Sarah Bernhardt", "role": "Actress; plays Jeanne d'Arc at the Porte Saint-Martin in the spring and Sardou's Cléopâtre from 23 October, before her world tour of 1891.", "real": true}, {"name": "Pauline Viardot", "role": "Singer and composer, 69; still hosts her musical Thursdays on the rue de Douai, beside Turgenev's empty chair.", "real": true}, {"name": "Jules Massenet", "role": "Composer; Esclarmonde, written for Sibyl Sanderson, is the success of the Opéra-Comique.", "real": true}, {"name": "Sibyl Sanderson", "role": "American soprano, 25; Massenet's Esclarmonde.", "real": true}, {"name": "Gabriel Fauré", "role": "Composer; choirmaster at La Madeleine. His Requiem is being expanded for full orchestra.", "real": true}, {"name": "Claude Debussy", "role": "Composer, 27; back from the Villa Medici with a Prix de Rome and very little money.", "real": true}, {"name": "Erik Satie", "role": "Composer, 24; second pianist at Rodolphe Salis's Chat Noir, author of the Gymnopédies.", "real": true}, {"name": "Rodolphe Salis", "role": "Proprietor of the cabaret Le Chat Noir on the rue de Laval.", "real": true}, {"name": "Aristide Bruant", "role": "Chansonnier, 39; insults his customers nightly at Le Mirliton on the boulevard Rochechouart.", "real": true}, {"name": "Emmanuel Chabrier", "role": "Composer of España and Gwendoline.", "real": true}, {"name": "Ignacy Jan Paderewski", "role": "Polish pianist, 29, the sensation of the Paris concert halls since 1888.", "real": true}, {"name": "Auguste Rodin", "role": "Sculptor; still at work on the Gates of Hell at the Dépôt des Marbres, and commissioned in 1889 for a monument to Victor Hugo.", "real": true}, {"name": "Gustave Eiffel", "role": "Engineer, 57; keeps a laboratory at the top of his tower, completed in 1889.", "real": true}, {"name": "Nadar", "role": "Photographer, balloonist and inexhaustible talker, 70.", "real": true}, {"name": "Charles Garnier", "role": "Architect of the Opéra, who knows its every cellar.", "real": true}];
export const MISSIONS=[{"id": "m1", "n": 1, "fac": "avant", "chapter": 0, "title": "La Grippe", "en": "The Influenza", "brief": "January. The Russian influenza has put half of Paris to bed, and a yellow fog lies on the Seine like wet wool. Théo comes home from the chemist on rue Mouffetard and finds the workshop door standing open to the cold.", "steps": [{"t": "goto", "at": "cellier", "time": 90, "foot": false, "text": "Run home to Maître Vallet's workshop before the trail goes cold."}, {"t": "kill", "at": "cellier", "n": 2, "armed": false, "boss": false, "say": ["Masked man: Leave it, Jojo, it's only the boy!"], "text": "Two masked men are still at the strongbox. Throw them out."}, {"t": "goto", "at": "hoteldieu", "time": 80, "foot": false, "say": ["Vallet: Never mind my head. The case, Théo. Is the tourbillon in its case?"], "text": "Vallet is bleeding from the scalp. Fetch a surgeon from the Hôtel-Dieu, and run."}, {"t": "goto", "at": "cellier", "text": "Bring the surgeon back to the workshop."}], "reward": 1850, "respect": 6, "heist": false, "intro": ["Théo: Nineteen clocks on the wall, and every one of them stopped at a quarter past two. Somebody wanted me to know the hour."], "outro": ["Surgeon: A clean blow, expertly given. Your thieves did not wish to kill him, only to keep him quiet.", "Théo: The case is empty, Maître. They left the gold and took the regulator.", "Vallet: Then they are not thieves. Thieves take gold."], "card": true}, {"id": "m2", "n": 2, "fac": "avant", "chapter": 0, "title": "Une Plume de Pie", "en": "A Magpie's Feather", "brief": "In the empty velvet of the case lies a single black-and-white feather, laid there with care. Henri Vautrin, who knows every rooftop in Montmartre, knows who leaves feathers.", "steps": [{"t": "goto", "at": "bateau", "text": "Find Henri at the piano works on rue Ravignan."}, {"t": "steal", "vtype": "gig", "at": "bateau", "text": "Borrow the coal-merchant's gig. Henri will square it with him. Probably."}, {"t": "race", "cps": ["tertre", "abbesses", "ratmort"], "time": 55, "say": ["Henri: There! On the roof of the laundry! Nobody runs on wet slates like that unless they are paid to."], "text": "A masked rider on the rooftops! Keep her in sight down the hill."}, {"t": "goto", "at": "ratmort", "text": "She is gone, but she dropped something outside the Café du Rat Mort. Look."}], "reward": 2200, "respect": 6, "heist": false, "loot": "Magpie feather", "intro": ["Henri: A feather? Mon vieux, that is a signature. La Pie, they call her. She robs only the rich, which is to say she has never robbed me."], "outro": ["Théo: A pawn ticket from the Mont-de-Piété. Number 4471.", "Henri: Either she is careless, or she wanted you to have it. I cannot decide which frightens me more."]}, {"id": "m3", "n": 3, "fac": "apache", "chapter": 0, "title": "Le Chien qui Fume", "en": "The Smoking Dog", "brief": "Every stolen thing in Paris passes through Maza's back room at Les Halles sooner or later, in a basket, under the cabbages. She will talk to Théo, if he brings her a present first.", "steps": [{"t": "steal", "vtype": "brougham", "at": "boulevard", "text": "Take a gentleman's brougham on the Boulevard des Italiens while its owner dines at Tortoni."}, {"t": "deliver", "at": "chien", "time": 0, "text": "Bring it to Au Chien qui Fume. Maza's people will strip it before the soup is cold."}, {"t": "eaves", "at": "chien", "time": 24, "say": ["Customer: Nobody will touch the regulator, Maza. It's promised. A great house.", "Maza: Promised by whom?", "Customer: By a man who has more friends at the Préfecture than you have rats.", "Maza: Nobody has more friends than I have rats, chéri."], "text": "Wait in the back room, close enough to hear Maza's other customer."}, {"t": "goto", "at": "chien", "fence": 400, "text": "Collect what Maza pays for the brougham."}], "reward": 2550, "respect": 6, "heist": false, "intro": ["Maza: A watchmaker's boy in my house at this hour? Either someone has died or someone owes. Bring me something with wheels, mon petit, and then we talk."], "outro": ["Maza: You heard? Good. Then I needn't repeat myself, which I never do. Your clock is spoken for by someone with a coronet. Be careful whom you annoy, mon petit."]}, {"id": "m4", "n": 4, "fac": "apache", "chapter": 0, "title": "Glace et Charbon", "en": "Ice and Coal", "brief": "The winter has made coal dearer than wine, and Maza has a wagon of it that does not, strictly speaking, belong to her. Favours are the only coin she does not count.", "steps": [{"t": "steal", "vtype": "gig", "at": "bercy", "text": "Take the coal wagon from the Bercy depots."}, {"t": "deliver", "at": "halles", "time": 0, "text": "Drive it to the Halles pavilions."}, {"t": "destroy", "at": "halles", "n": 2, "say": ["Théo: Chalk crosses on every second sack. Somebody expected this wagon."], "text": "Twist: Mourier's agents have marked the sacks with chalk to trace them. Burn the marked sacks before they are counted."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "The sergents de ville smell smoke. Lose them."}], "reward": 2900, "respect": 6, "heist": false, "intro": ["Maza: One wagon of coal from Bercy to the pavilions before dawn. Nobody hurt, nobody seen, and you stop asking me questions for one whole night."], "outro": ["Maza: Chalk! The inspector marks my coal like a schoolmaster. You did well. I shall remember it, and I remember very little."]}, {"id": "m5", "n": 5, "fac": "avant", "chapter": 0, "title": "Chez le Père Tanguy", "en": "At Père Tanguy's", "brief": "Old Tanguy grinds colours on rue Clauzel and gives credit to any painter who looks hungry. A customer paid him last week with a gold watch-key engraved A.V.", "steps": [{"t": "goto", "at": "tanguy", "text": "Call on Père Tanguy at his colour shop, rue Clauzel."}, {"t": "eaves", "at": "tanguy", "time": 20, "say": ["Customer: Lead white. All you have. And bitumen.", "Tanguy: Bitumen cracks, monsieur, in twenty years.", "Customer: That is precisely the point, old man.", "Tanguy: (to Théo, after) He wanted his pictures to look old the day they were born. A forger's quantity, I said to myself."], "text": "Tanguy is serving a customer. Keep your distance and listen."}, {"t": "collect", "at": "batignolles", "n": 3, "text": "The customer's servant threw canvas scraps on the rubbish heaps of the Batignolles. Recover three."}], "reward": 3250, "respect": 6, "heist": false, "loot": "Watch-key 'A.V.'", "intro": ["Tanguy: You are Vallet's boy? Then you are welcome. Mind the Cézannes, nobody buys them, but they still bite."], "bonus": {"at": "batignolles", "pay": 600, "text": "A torn sketchbook page lies in the snow near the scraps. It might be worth something to someone."}, "outro": ["Tanguy: Your watch-key, my boy. A.V. Augustin Vallet. Your master's own initials. Whoever paid me with it was laughing at both of us."]}, {"id": "m6", "n": 6, "fac": "avant", "chapter": 0, "title": "Le Moineau", "en": "The Sparrow", "brief": "A barefoot urchin has been watching the workshop for three days. Children do not keep watch for free in January. Follow him and see who pays.", "steps": [{"t": "tail", "at": "tanguy", "to": "ratmort", "say": ["Moineau: (whistling) Au clair de la lune...", "Moineau: (to a passing soldier) Spare a sou, mon général?", "Moineau: (to himself) Two francs. Two francs for watching a boy watch clocks."], "text": "Follow Moineau down the hill without being seen. He looks behind him at every corner."}, {"t": "eaves", "at": "ratmort", "time": 18, "say": ["Man: Still at the workshop, the apprentice?", "Moineau: Every night. He sleeps in the shavings.", "Man: Then tell La Pie her bird has flown into the right cage. Here. Don't drink it."], "text": "He meets a man outside the Rat Mort. Get close enough to hear."}, {"t": "choice", "key": "moineau", "at": "abbesses", "to": "ratmort", "ra": "Théo: Go on. Tell La Pie I said good evening. Moineau: You're soft, monsieur. I'll remember that. In a good way.", "rb": "Maza's man: Maza will teach him a better trade. Here's for your trouble. Théo: (pocketing it) Then why do I feel I have sold something?", "pay": [0, 900], "text": "You have the boy by the collar. Let him go free at the Abbesses, or hand him to Maza's man at the Rat Mort."}], "reward": 3600, "respect": 6, "heist": false, "intro": ["Henri: The little one with the cap? Moineau, they call him. Sharp as a tack. Sold me a dead pigeon once as a live one."], "outro": ["Théo: La Pie has a bird-keeper. And La Pie answers to someone who pays in silver."]}, {"id": "m7", "n": 7, "fac": "crimson", "chapter": 0, "title": "Retour de Genève", "en": "Back from Geneva", "brief": "Lucie Arnoux, engraver and former forger, has slipped back over the Swiss border with a forger's sentence still hanging over her. She can read a scrap of canvas the way a priest reads a confession.", "steps": [{"t": "goto", "at": "procope", "text": "Meet Lucie at the Café Procope, the oldest café in Paris and the least discreet."}, {"t": "escort", "at": "procope", "to": "printers", "real": false, "text": "Walk her to her old press on rue de la Harpe. Keep off the main streets."}, {"t": "kill", "at": "printers", "n": 3, "armed": false, "boss": false, "say": ["Lucie: Landlords. In the Commune we were going to abolish them. We ran out of time."], "text": "Twist: her landlord sold her for twenty francs. Mourier's informers are waiting."}, {"t": "collect", "at": "printers", "n": 2, "text": "Gather the tools the informers threw into the snow: her burin and her loupe."}], "reward": 3950, "respect": 6, "heist": false, "intro": ["Lucie: Don't say my name in this café, it still has a price on it. Sit. Order something hot and look bored. You are very good at it already."], "outro": ["Lucie: (studying the scraps) Primed with lead white, smoked over a lamp, rolled to crack. Someone is making old masters in a warm room, Théo, and very fast."]}, {"id": "m8", "n": 8, "fac": "crimson", "chapter": 0, "title": "Le Blanc de Plomb", "en": "Lead White", "brief": "Lucie suspects the forgeries are being sold at the Hôtel Drouot, where a fortune changes hands every afternoon and nobody asks where anything came from.", "steps": [{"t": "goto", "at": "drouot", "text": "Go to the Hôtel Drouot."}, {"t": "sneak", "at": "drouot", "n": 2, "r": 7.0, "text": "Slip past the porters into the viewing rooms. Stay out of their sight lines."}, {"t": "collect", "at": "drouot", "n": 3, "stealth": true, "text": "Chalk-mark three suspect canvases for Lucie. Raise no alarm."}, {"t": "eaves", "at": "drouot", "time": 20, "say": ["Englishman: Lot forty-two. A Corot, quite authentic, I assure you. I painted it myself, very nearly.", "Auctioneer: Monsieur Crane is droll.", "Crane: Monsieur Crane is paid. Mark the provenance to the Vaneau collection, there's a good fellow."], "text": "Twist: an Englishman is bidding against nobody, and winning. Listen."}, {"t": "goto", "at": "printers", "text": "Bring the lot numbers back to Lucie."}], "reward": 5800, "respect": 6, "heist": true, "intro": ["Lucie: The auction rooms open to view at eleven. Look at the backs of the pictures, not the fronts. The fronts are for fools."], "outro": ["Lucie: Crane. Silas Crane. He forged bank notes in Brussels and Turners in London, and now he forges France. And he works for a baron."]}, {"id": "m9", "n": 9, "fac": "velvet", "chapter": 0, "title": "Le Baron", "en": "The Baron", "brief": "A gilded card arrives at the wrecked workshop: Baron Léopold Vaneau wishes to commission a clock for his box at the Opéra, and asks for the apprentice by name.", "steps": [{"t": "goto", "at": "cafepaix", "text": "Meet the Baron's secretary at the Café de la Paix."}, {"t": "escort", "at": "cafepaix", "to": "garnier", "real": false, "text": "Drive the secretary to the Opéra. He talks the entire way and says nothing at all."}, {"t": "eaves", "at": "garnier", "time": 22, "say": ["Vaneau: The boy is to be watched, Mourier, not touched. A frightened apprentice is useless to me.", "Mourier: And a dead one is quieter.", "Vaneau: Quiet is cheap, Inspector. I prefer things that are dear."], "text": "Twist: on the grand staircase the Baron is speaking with a man in a policeman's overcoat. Listen from the balustrade."}, {"t": "goto", "at": "garnier", "text": "Present yourself to the Baron."}], "reward": 4650, "respect": 6, "heist": false, "intro": ["Théo: He asks for me, not for my master. Either he knows Vallet is hurt, or he did the hurting."], "outro": ["Vaneau: Your master's work was exquisite. Was. I shall need a clock for my box, Monsieur Marchal, and I am told you have very steady hands. Let us see whether you have steady nerves."]}, {"id": "m10", "n": 10, "fac": "apache", "chapter": 0, "title": "Inspecteur Mourier", "en": "Inspector Mourier", "brief": "Inspector Mourier has decided that the apprentice robbed his own master. There is a warrant, and the warrant has a reward attached.", "steps": [{"t": "survive", "lvl": 2, "time": 25, "alarm": true, "text": "Mourier's men close the streets around Les Halles. Survive the net."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "Lose the police."}, {"t": "goto", "at": "catacombs", "time": 150, "foot": true, "text": "Twist: every bridge is watched. Cross on foot and go to ground at the Catacombs at Denfert, before the barrier closes."}], "reward": 6500, "respect": 6, "heist": true, "intro": ["Maza: Your inspector wants you in the Dépôt by tonight. He has told every concierge in Paris. They are all deciding what you are worth."], "outro": ["Théo: Six million dead Parisians under the city, and not one of them asks me for papers.", "Lucie: (by note) Stay underground two nights. Then come to me. We have work."]}, {"id": "m11", "n": 11, "fac": "avant", "chapter": 0, "title": "Le Bal de la Galette", "en": "The Ball at the Galette", "brief": "Sunday at the Moulin de la Galette: dancing, cheap wine and masks. Henri says La Pie will be fencing a watch movement among the dancers.", "steps": [{"t": "steal", "vtype": "phaeton", "at": "monceau", "text": "Steal a phaeton near the Parc Monceau. One cannot arrive at a ball on foot."}, {"t": "escort", "at": "batignolles", "to": "galette", "real": false, "text": "Collect Henri's two models in the Batignolles and drive them up to the Galette."}, {"t": "eaves", "at": "galette", "time": 24, "say": ["Masked woman: A regulator, they say. Twenty-four jewels.", "Masked man: And twenty-four buyers, all lying.", "Masked woman: La Pie will sell to only one. She says the Baron would rather it were never found.", "Masked man: Then why steal it at all?", "Masked woman: To make an apprentice come looking."], "text": "Drift among the dancers near the bandstand, and listen for talk of a watch."}, {"t": "kill", "at": "galette", "n": 3, "armed": true, "boss": false, "say": ["Henri: Owls, I said! Not peacocks! You strutted, Théo!"], "text": "Twist: Vaneau's men have recognised your walk, mask or no. Drive them off."}], "reward": 5350, "respect": 6, "heist": false, "intro": ["Henri: Wear this mask. No, the other way up. There. You look like a disappointed owl. Perfect, nobody looks twice at owls."], "outro": ["Théo: She took the tourbillon to make me come looking. Then the Baron wants me looking. The question is, what does he want me to find?"]}, {"id": "m12", "n": 12, "fac": "crimson", "chapter": 0, "title": "Les Cuivres", "en": "The Copperplates", "brief": "Mourier has seized Lucie's copperplates and taken them to the Préfecture. With them she can prove which prints are hers and which are Crane's.", "steps": [{"t": "goto", "at": "prefecture", "text": "Go to the Préfecture de Police on the Île de la Cité."}, {"t": "sneak", "at": "prefecture", "n": 3, "r": 8.0, "text": "Get past the night watch in the courtyard. Keep to the shadows."}, {"t": "collect", "at": "prefecture", "n": 2, "stealth": true, "text": "Take the copperplates from the evidence shelves unseen."}, {"t": "eaves", "at": "prefecture", "time": 16, "say": ["Clerk: (muttering) Vaneau, five hundred... Vaneau, five hundred... Vaneau, a case of champagne for Madame Mourier.", "Clerk: The Inspector's wife drinks well for a policeman's wife."], "text": "Twist: a ledger lies open on the clerk's desk. Read it over his shoulder."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "Slip away across the Pont Saint-Michel."}], "reward": 7200, "respect": 6, "heist": true, "loot": "Lucie's copperplates", "intro": ["Lucie: The evidence room is on the second floor, behind the clerks of the Sûreté. The clerks sleep at four. I know, because I used to be their evidence."], "outro": ["Lucie: My plates. And you read his ledger too? Théo Marchal, you may yet become a criminal worth knowing."]}, {"id": "m13", "n": 13, "fac": "avant", "chapter": 0, "title": "La Clé de Montre", "en": "The Watch-Key", "brief": "Pawn ticket 4471 leads not to a pawnshop but to a locker in the left-luggage office at the Gare Saint-Lazare, which the watch-key fits exactly.", "steps": [{"t": "steal", "vtype": "brougham", "at": "gare", "text": "Take a cab at Saint-Lazare as cover."}, {"t": "sneak", "at": "gare", "n": 3, "r": 8.0, "text": "Reach the left-luggage counter without the railway police noticing."}, {"t": "collect", "at": "gare", "n": 2, "stealth": true, "text": "Search the locker and the porter's book."}, {"t": "race", "cps": ["batignolles", "monceau", "arc"], "time": 65, "say": ["La Pie: Too slow, little watchmaker! You wind your legs like you wind your clocks!"], "text": "Twist: a cloaked figure snatches the box from under your hands. Chase her to the Étoile!"}], "reward": 7550, "respect": 6, "heist": true, "loot": "Empty tourbillon case", "intro": ["Théo: Someone wanted me to find the key, and the ticket, and now the locker. One does not leave so many breadcrumbs unless one wants the bird to follow."], "outro": ["Théo: She threw it back to me from the Arc. An empty tourbillon case, with a card inside: 'Not yet.'", "Henri: Romantic. Thoroughly criminal, and romantic."]}, {"id": "m14", "n": 14, "fac": "crimson", "chapter": 0, "title": "Les Mardis de la rue de Rome", "en": "Tuesdays on the rue de Rome", "brief": "On Tuesday evenings Stéphane Mallarmé receives poets in his small apartment by the Saint-Lazare tracks. A guest there knows Crane's English alias.", "steps": [{"t": "escort", "at": "procope", "to": "gare", "real": false, "text": "Escort Lucie across the river to the rue de Rome."}, {"t": "eaves", "at": "gare", "time": 26, "say": ["Mallarmé: To name a thing, monsieur, is to destroy three quarters of the pleasure of the poem.", "Guest: Your Englishman, Mallarmé, the one who quotes Keats so badly?", "Mallarmé: He signs his letters S.C. and his paintings with other men's names. A man so modest he will not even be himself.", "Mallarmé: He asked me where one buys a great deal of gilt. Gilt, monsieur. Not gold."], "text": "Mallarmé's salon. Stand by the stove and listen."}, {"t": "tail", "at": "gare", "to": "staugustin", "say": ["Guest: (to his cabman) No. Walk. I need the air.", "Guest: (under his breath) Twelve. He said twelve. Twelve of what?"], "text": "Twist: a guest leaves early and in a hurry. Follow him to Saint-Augustin."}, {"t": "goto", "at": "staugustin", "text": "He enters the church by the side door. Go in after him."}], "reward": 6400, "respect": 6, "heist": false, "intro": ["Lucie: The poets talk in riddles and drink tea. You will hate it. Listen anyway."], "outro": ["Théo: He was looking at the clock in the tower, not the altar. And making notes.", "Lucie: Then we have a man who prays to clocks."]}, {"id": "m15", "n": 15, "fac": "velvet", "chapter": 0, "title": "L'Horloge du Baron", "en": "The Baron's Clock", "brief": "Théo has accepted the Baron's commission, as a way inside. The great clock for Vaneau's box needs measuring, and the Opéra's architect has his own opinions on who may touch his building.", "steps": [{"t": "goto", "at": "garnier", "text": "Present yourself at the Opéra's artists' entrance."}, {"t": "collect", "at": "garnier", "n": 3, "text": "Take the measurements of the Baron's box: height, depth, the angle of the gaslight."}, {"t": "eaves", "at": "garnier", "time": 18, "say": ["Garnier: Below us, the reservoir. Water, monsieur, to keep the foundations from floating away.", "Crane: And the old cellar under the Baron's box?", "Garnier: There is no cellar under the Baron's box.", "Crane: How curious. He told me there was."], "text": "Twist: Garnier is showing an English visitor the cellars. Listen."}, {"t": "smash", "at": "bourse", "n": 4, "say": ["Théo: (to himself) A dirty test for a dirty employer. I'll break the furniture and spare the clocks."], "text": "The Baron's clerk tests your nerve: wreck the office of a rival watchmaker near the Bourse."}], "reward": 6750, "respect": 6, "heist": false, "intro": ["Charles Garnier: You are the clockmaker? Mind you do not drill my marble. Every Baron in Paris thinks he owns a piece of this house. They own a box. I own the building, in the only way that matters."], "outro": ["Vaneau: You broke his desks and left his clocks ticking. Sentimental. I find I like you, Monsieur Marchal. That is unfortunate for one of us."]}, {"id": "m16", "n": 16, "fac": "apache", "chapter": 0, "title": "Les Glaçons", "en": "The Ice Floes", "brief": "A barge with the Baron's crest is locked in the ice at the Ivry wharves. Maza's watermen swear it carries Crane's crates. When the thaw comes it will slip away for Le Havre.", "steps": [{"t": "goto", "at": "ivry", "text": "Go to the Ivry wharves."}, {"t": "sneak", "at": "ivry", "n": 3, "r": 8.0, "text": "Cross the ice to the barge without the bargemen seeing you."}, {"t": "collect", "at": "ivry", "n": 1, "stealth": true, "text": "Lift Maza's crate first."}, {"t": "destroy", "at": "ivry", "n": 3, "text": "Twist: the crates hold not paintings but blank canvases, stretched and aged for forgeries. Torch them."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "The river brigade is coming over the ice. Lose them."}], "reward": 8600, "respect": 6, "heist": true, "intro": ["Maza: Burn it or sink it, I don't care which. But I want one crate, unburnt, for my trouble. I am a businesswoman."], "outro": ["Maza: (prising the lid) Gilt frames. Empty gilt frames, each with a museum label. Your forger works backwards, mon petit: frame first, picture after."]}, {"id": "m17", "n": 17, "fac": "crimson", "chapter": 0, "title": "Le Faux Corot", "en": "The False Corot", "brief": "Crane's first forgery to surface is a Corot hanging at Goupil's on the rue Chaptal. Lucie has painted a copy of the copy, with her mark hidden in the varnish, so the next sale can be traced.", "steps": [{"t": "goto", "at": "goupil", "text": "Go to Goupil et Cie."}, {"t": "sneak", "at": "goupil", "n": 3, "r": 8.0, "text": "Get past the shopmen to the back gallery."}, {"t": "collect", "at": "goupil", "n": 1, "stealth": true, "swap": true, "text": "Swap Crane's forgery for Lucie's marked copy."}, {"t": "survive", "lvl": 1, "lose": true, "time": 0, "text": "Leave quietly, and don't run. Men who run are men who have done something."}], "reward": 8950, "respect": 6, "heist": true, "loot": "Forged 'Corot' (evidence)", "intro": ["Lucie: Mine is better than his, naturally. Don't let them see you carrying it, a painting under the arm is the only thing more suspicious than a pistol."], "outro": ["Lucie: Now every buyer of that Corot carries my signature home. We can follow the money like a thread through a needle."]}, {"id": "m18", "n": 18, "fac": "crimson", "chapter": 0, "title": "L'Imprimerie Clandestine", "en": "The Secret Press", "brief": "Crane prints false certificates of provenance by the hundred. A paper merchant on the Boulevard Saint-Michel has been selling museum-grade paper to a man with no museum.", "steps": [{"t": "tail", "at": "boulmich", "to": "printers", "say": ["Paper-boy: (singing) Le temps des cerises...", "Paper-boy: (stopping to look behind him) ...", "Paper-boy: Good evening, Madame Lebrun. No, it's not for the Sorbonne, it's for the Englishman."], "text": "Tail the paper-boy from the Boulevard Saint-Michel. He takes a long way round."}, {"t": "kill", "at": "printers", "n": 4, "armed": true, "boss": false, "text": "Crane's guards defend the press, and they are armed."}, {"t": "destroy", "at": "printers", "n": 2, "text": "Smash the press and burn the certificates."}, {"t": "collect", "at": "printers", "n": 2, "text": "Twist: Crane's order book survives. Save the two pages that matter."}], "reward": 7800, "respect": 6, "heist": false, "intro": ["Lucie: Follow the paper. Paper always goes home to a press, the way a dog goes home to its master."], "outro": ["Théo: An order book. Twelve clocks are listed, with names beside them: Saint-Augustin, the Bourse, the Châtelet...", "Lucie: Twelve churches and halls. That is not forgery. That is architecture."]}, {"id": "m19", "n": 19, "fac": "apache", "chapter": 0, "title": "Le Dégel", "en": "The Thaw", "brief": "The ice is breaking. Maza's watermen say the tourbillon itself was seen being carried aboard a second barge below Notre-Dame. Mourier's men are guarding it.", "steps": [{"t": "steal", "vtype": "phaeton", "at": "concorde", "text": "Take a fast phaeton at the Concorde."}, {"t": "race", "cps": ["concorde", "louvre", "notredame"], "time": 60, "text": "Race along the quais before the barge casts off."}, {"t": "kill", "at": "notredame", "n": 4, "armed": true, "boss": true, "text": "Board the barge and fight Mourier's hired men. Their leader is armed."}, {"t": "collect", "at": "notredame", "n": 1, "text": "Open the strongroom in the barge's hold."}], "reward": 8150, "respect": 6, "heist": false, "intro": ["Maza: One hour until the river runs again. After that your clock goes to Le Havre, and from Le Havre to anywhere."], "outro": ["Théo: Empty, but for a crate stamped with the Baron's crest and a note in La Pie's hand: 'He was never going to send it away. He needs it here.'"]}, {"id": "m20", "n": 20, "fac": "avant", "chapter": 0, "title": "Fin de l'Hiver", "en": "Winter's End", "brief": "The last snow is turning to slush on the rue Mouffetard. Maître Vallet is well enough to sit up, and to tell Théo what he should have told him long ago.", "steps": [{"t": "goto", "at": "bateau", "text": "Collect Henri at the piano works."}, {"t": "goto", "at": "cellier", "time": 120, "foot": false, "text": "Get to the workshop before Vallet's strength fails him."}, {"t": "eaves", "at": "cellier", "time": 28, "say": ["Vallet: I did not build the tourbillon for a client, Théo. I built it for a lock.", "Vallet: Twelve chiming clocks, all regulated by one master. When they strike together, in a certain order, a door opens.", "Théo: A door where?", "Vallet: Under the Opéra. Garnier never knew. The Baron paid me to build the key, and when I understood what it opened, I refused to give it to him.", "Vallet: So he came for it in the night."], "text": "Sit by Vallet's bed, and listen."}], "reward": 8500, "respect": 6, "heist": false, "intro": ["Henri: He's asked for you. He's asked for his loupe and his tobacco too, so he's either recovering or preparing a deathbed speech."], "outro": ["Vallet: Spring is coming, and the Salon. Every collector in Paris will be in one room. Go and watch them, Théo. Somebody will be looking at the wrong picture."]}, {"id": "m21", "n": 21, "fac": "avant", "chapter": 1, "title": "Les Indépendants", "en": "The Independents", "brief": "20 March. The Société des Artistes Indépendants opens its sixth exhibition in the Pavillon de la Ville de Paris on the Champs-Élysées, and Monsieur Signac needs a watchman he can trust. Henri has vouched for Théo, which Signac regards as a point against him.", "steps": [{"t": "goto", "at": "industrie", "text": "Report to Signac at the Pavillon de la Ville de Paris, beside the Palais de l'Industrie."}, {"t": "eaves", "at": "industrie", "time": 22, "say": ["First gentleman: Dots. Ten thousand dots, and not one of them a face.", "Second gentleman: Then why are you measuring them, Albert?", "First gentleman: The Baron wants the sizes. He says he can sell a daub very dear, provided it has a famous name.", "Degas: (passing) And a famous frame, no doubt."], "text": "Walk the rooms. Watch the walls, not the visitors, and listen to two gentlemen at the Cassatts."}, {"t": "kill", "at": "industrie", "n": 3, "armed": false, "boss": false, "say": ["Seurat: (quietly) Not that one. It took a year. Every point of it took a year."], "text": "Twist: at closing time three men produce knives and go for the canvases. Stop them."}], "reward": 8850, "respect": 8, "heist": false, "intro": ["Signac: You are the clockmaker. Good. Clockmakers look at things closely and say nothing. Painters look at nothing and say everything. Monsieur Seurat will tell you which pictures matter. He will say all of them, in a whisper."], "outro": ["Signac: You will stay on as watchman until the twenty-seventh. Thirty francs a week and no opinions. Mademoiselle Cassatt came to look yesterday, and saw something. Ask her; she is the only one of us with any sense."], "card": true}, {"id": "m22", "n": 22, "fac": "avant", "chapter": 1, "title": "Mademoiselle Cassatt", "en": "Miss Cassatt", "brief": "Mary Cassatt noticed a copyist at her pastels who worked far too well and far too fast. She would like Théo to walk with her to the Tuileries, where she says she last saw him.", "steps": [{"t": "escort", "at": "industrie", "to": "tuileriesg", "real": true, "text": "Escort Mademoiselle Cassatt to the Tuileries gardens."}, {"t": "goto", "at": "tuileriesg", "text": "Cassatt: There. By the ruined palace, with the folding stool. He has a painter's hands and a bookkeeper's eyes."}, {"t": "tail", "at": "tuileriesg", "to": "vendome", "say": ["Copyist: (to a nursemaid) Charming child. Hold still, I shall have him in three strokes.", "Copyist: (counting under his breath) Four Cassatts, two Degas, one Morisot.", "Copyist: (at the Rue de Castiglione) Damn the man, he is always early."], "text": "Follow the copyist without alarming him."}, {"t": "eaves", "at": "vendome", "time": 18, "say": ["Crane: You copied her line, not her mind, old chap. These children have no weight in them.", "Copyist: The buyers don't look at weight, they look at the name.", "Crane: The Baron's buyers will look very carefully. Do them again."], "text": "Twist: under the Vendôme Column he meets Silas Crane. Listen."}], "reward": 9200, "respect": 8, "heist": false, "intro": ["Cassatt: In Philadelphia we would simply ask the man what he was doing. In Paris that is considered vulgar, so we follow him instead."], "outro": ["Cassatt: (later, by letter) I have seen the copies. They are clever. That is the worst I can say of any picture. Tell me how I may help."]}, {"id": "m23", "n": 23, "fac": "crimson", "chapter": 1, "title": "La Bête Humaine", "en": "The Human Beast", "brief": "Zola's railway novel is in every bookseller's window, and Maupassant's Notre Cœur is running in the Revue des Deux Mondes, so the boulevard can talk of nothing but novelists. Maupassant, it seems, has dined with a Baron who asked a great deal about clocks.", "steps": [{"t": "goto", "at": "procope", "text": "Meet Lucie at the Procope."}, {"t": "eaves", "at": "procope", "time": 24, "say": ["Maupassant: Boule de Suif is a fat girl in a carriage, my friends, and she is the only honest person in France.", "Friend: And your Baron?", "Maupassant: Vaneau? He collects people the way he collects pictures, with the price still pinned to the frame. He asked me whether I knew any good clockmakers. I said I knew only bad poets.", "Maupassant: He laughed. Men like that only laugh when they are counting."], "text": "Maupassant holds court at the next table. Listen."}, {"t": "escort", "at": "procope", "to": "odeon", "real": true, "text": "Walk Monsieur de Maupassant to the Odéon, where he means to look at the actresses."}, {"t": "goto", "at": "odeon", "text": "Maupassant: You want to know about the Baron? Then a word of advice, from a man at the Ministry of the Marine. He keeps two ledgers. One for the tax man, and one for God."}], "reward": 9550, "respect": 8, "heist": false, "intro": ["Lucie: Maupassant drinks at the Procope after the Odéon. He will tell you everything if you let him think it was his idea."], "outro": ["Lucie: Two ledgers. If we find the second one, we have him. If he finds us looking, he has us."]}, {"id": "m24", "n": 24, "fac": "velvet", "chapter": 1, "title": "Le Jury", "en": "The Jury", "brief": "The official Salon fills the Palais de l'Industrie. Vaneau sits on a committee that hangs the pictures, and he wants Monet's old Lavacourt, lent by a collector to the retrospective room, to 'go missing' before the critics see it. Théo plays along, and hides it to save it.", "steps": [{"t": "goto", "at": "industrie", "text": "Go to the Palais de l'Industrie."}, {"t": "sneak", "at": "industrie", "n": 3, "r": 9.0, "text": "Get past the Salon guardians to the store-rooms."}, {"t": "collect", "at": "industrie", "n": 2, "stealth": true, "text": "Take the Lavacourt and its frame, unseen."}, {"t": "deliver", "at": "bateau", "time": 0, "fragile": true, "text": "Carry it to Henri's at the piano works. It is a Monet: drive as if it were made of eggshell."}], "reward": 11400, "respect": 8, "heist": true, "loot": "Monet's Lavacourt (rescued)", "intro": ["Vaneau: Monsieur Monet is going about Paris with a subscription list, collecting money to buy Manet's Olympia for the nation. The nation does not want it. Let him learn what it costs to embarrass men of taste. You will make his picture vanish. Do it well and you have a friend for life. Do it badly and you have me."], "outro": ["Henri: (unwrapping it) The Seine at Lavacourt, in winter, with the ice on it. He paints cold like other men paint fire.", "Théo: Tomorrow it goes back on the wall, the right way up, before the critics come. Vaneau will think his own men bungled it."]}, {"id": "m25", "n": 25, "fac": "apache", "chapter": 1, "title": "Le Receleur", "en": "The Fence", "brief": "Maza has heard that a buyer is shopping in the Marais for a 'regulator movement of exceptional quality'. Buyers like that have middlemen, and middlemen have weak knees.", "steps": [{"t": "steal", "vtype": "brougham", "at": "bastille", "text": "Take a brougham at the Bastille."}, {"t": "kill", "at": "cirquehiver", "n": 3, "armed": true, "boss": false, "text": "Shake down the middlemen behind the Cirque d'Hiver. One of them has a revolver."}, {"t": "collect", "at": "cirquehiver", "n": 2, "text": "Collect the silver they dropped in their hurry."}, {"t": "goto", "at": "chien", "fence": 900, "text": "Sell their silver to Maza."}], "reward": 10250, "respect": 8, "heist": false, "intro": ["Maza: Three of them, behind the Cirque d'Hiver. Persuade them. I do not mean with poetry."], "outro": ["Maza: They told me, between sobs, that the buyer was not buying. He was making sure nobody else could. The Baron is cornering the market in your master's clocks, mon petit."]}, {"id": "m26", "n": 26, "fac": "crimson", "chapter": 1, "title": "Sarah en Jeanne", "en": "Sarah as Joan", "brief": "April. Sarah Bernhardt is playing Jeanne d'Arc at the Porte Saint-Martin, and the crowd at the stage door is larger every night. Crane means to use the crush to lift a portrait from the theatre foyer.", "steps": [{"t": "goto", "at": "republique", "text": "Go to the Théâtre de la Porte Saint-Martin, by the Place du Château-d'Eau."}, {"t": "kill", "at": "republique", "n": 3, "armed": true, "boss": false, "text": "Stop Crane's men under the portico before they reach the foyer."}, {"t": "escort", "at": "republique", "to": "stjacques", "real": true, "say": ["Bernhardt: They burn me at the stake eight times a week, monsieur. One learns to leave a theatre quickly."], "text": "Madame Bernhardt wants a way out through the crowd. See her safely to her carriage by the Tour Saint-Jacques."}, {"t": "goto", "at": "stjacques", "text": "Bernhardt: You have a kind face, young man. It will be the ruin of you. Come and see me when I am Cleopatra; it opens in October."}], "reward": 10600, "respect": 8, "heist": false, "intro": ["Lucie: Every journalist in Paris will be at the stage door. Nobody will be looking at the walls. Nobody but us."], "outro": ["Lucie: The portrait is safe. And you have been kissed on both cheeks by Sarah Bernhardt, which Henri will never forgive."]}, {"id": "m27", "n": 27, "fac": "avant", "chapter": 1, "title": "Au Bon Marché", "en": "At the Bon Marché", "brief": "Crane's forgeries are hung as decoration in the grands magasins, and sold quietly to rich clients who think they are buying a bargain. Lucie needs a catalogue of them.", "steps": [{"t": "goto", "at": "bonmarche", "text": "Go to Au Bon Marché."}, {"t": "sneak", "at": "bonmarche", "n": 3, "r": 9.0, "text": "The store detectives patrol the galleries. Keep out of their sight."}, {"t": "collect", "at": "bonmarche", "n": 4, "stealth": true, "text": "Mark four forgeries."}, {"t": "survive", "lvl": 1, "lose": true, "time": 0, "text": "Leave by the delivery yard."}], "reward": 12450, "respect": 8, "heist": true, "intro": ["Lucie: Four of them, in the salons on the first floor. Mark the stretchers with this. It glows under a lamp. Like guilt."], "bonus": {"at": "stsulpice", "pay": 800, "text": "A shopgirl dropped a sealed envelope addressed to 'S.C.' outside Saint-Sulpice. Retrieve it."}, "outro": ["Lucie: Four, and all of them sold to the same three families. They are not selling paintings, Théo. They are buying people."]}, {"id": "m28", "n": 28, "fac": "velvet", "chapter": 1, "title": "L'Entresol", "en": "The Mezzanine", "brief": "At Boussod, Valadon et Cie, the old house of Goupil, a young Dutch manager named Theo van Gogh keeps the pictures his employers dislike on the mezzanine. Vaneau asks Théo to 'collect' one for his private gallery. Instead Théo will plant a tracing behind it.", "steps": [{"t": "goto", "at": "goupil", "text": "Go to Boussod, Valadon et Cie."}, {"t": "eaves", "at": "goupil", "time": 20, "say": ["Van Gogh: Downstairs we sell what Paris already likes, madame. Up here I keep what it will like in twenty years.", "Van Gogh: (to Théo) You look at the pictures like a man looking for a door. What is behind the canvas, a mistress or a debt?", "Théo: A clock, monsieur.", "Van Gogh: Ah. That is worse. My brother would say a clock is only a sunflower that has learned arithmetic."], "text": "Monsieur van Gogh is showing the mezzanine to a visitor. Listen."}, {"t": "sneak", "at": "goupil", "n": 3, "r": 9.0, "text": "Wait for the gas to be lowered, then slip past the clerks."}, {"t": "collect", "at": "goupil", "n": 1, "stealth": true, "swap": true, "text": "Hide Lucie's tracing behind the canvas Vaneau wants. He can keep the frame and the empty ambition."}], "reward": 12800, "respect": 8, "heist": true, "intro": ["Vaneau: The little Monet upstairs, the cliffs. Take it after the gas is lowered. The Dutchman will never notice; he is far too busy apologising for his taste."], "outro": ["Théo: I left the cliffs where they were and stole the Baron's patience instead. Now, when his men take that painting, Lucie's tracing goes with it, and we will know where his gallery is."]}, {"id": "m29", "n": 29, "fac": "crimson", "chapter": 1, "title": "Le Petit Debussy", "en": "Young Debussy", "brief": "Claude Debussy, twenty-seven, back from Rome with a Prix de Rome and no money, gives lessons in the practice rooms of the Conservatoire. He has been making fun of an 'English music-lover' who copied out every manuscript in the library. Debussy, naturally, noticed.", "steps": [{"t": "goto", "at": "conservatoire", "text": "Go to the Conservatoire on the rue du Faubourg-Poissonnière."}, {"t": "eaves", "at": "conservatoire", "time": 22, "say": ["Debussy: (playing) What do you think of it, monsieur? It has no rules at all.", "Master: It has no manners, which is worse.", "Debussy: The Englishman asked for Monsieur Fauré's Requiem, the new score with the full orchestra. He wrote down every note. He sang it to himself, flat.", "Master: Monsieur Debussy, this room is for pupils, not for revolutions. The scale of D, please, and without improvements."], "text": "Debussy is improvising in a practice room while the masters argue in the corridor. Listen to both."}, {"t": "tail", "at": "conservatoire", "to": "heugel", "say": ["Copyist: (to himself) Pie Jesu... pie, pie, piece of luck..."], "text": "Twist: the Englishman's copyist is leaving with a satchel. Follow him to the music publisher Heugel."}, {"t": "kill", "at": "heugel", "n": 3, "armed": true, "boss": false, "text": "He is selling the copy to Crane's agents. Stop the sale."}], "reward": 11650, "respect": 8, "heist": false, "loot": "Copied score of Fauré's Requiem", "intro": ["Debussy: You are the police? No? A pity. I have always wanted to be arrested for an opinion."], "outro": ["Debussy: (by note, a week later) I hear you saved Monsieur Fauré from piracy. He was charming about it. He is charming about everything, which is very hard to forgive."]}, {"id": "m30", "n": 30, "fac": "avant", "chapter": 1, "title": "Le Jeudi de Madame Viardot", "en": "Madame Viardot's Thursday", "brief": "Pauline Viardot holds her musical Thursdays on the rue de Douai. Tonight an English tenor has been invited, and Lucie is fairly certain he is no tenor.", "steps": [{"t": "goto", "at": "lorette", "text": "Go to the rue de Douai, near Notre-Dame-de-Lorette."}, {"t": "eaves", "at": "lorette", "time": 26, "say": ["Viardot: Monsieur Crane, will you not sing for us?", "Crane: Alas, madame, I have a cold. An English cold. It lasts for years.", "Viardot: How sad. Then perhaps you will tell my guests why you were in my study.", "Crane: I was admiring your clock, madame. It is a Vallet.", "Viardot: It is, and it is mine. Ivan Sergeyevich gave it me. I should notice if it walked."], "text": "Stand at the back of the music room, and listen to the conversation under the music."}, {"t": "sneak", "at": "lorette", "n": 3, "r": 9.0, "text": "Twist: Crane has left a device inside Viardot's clock. Slip into the study unseen."}, {"t": "collect", "at": "lorette", "n": 1, "text": "Take out Crane's little brass cylinder."}], "reward": 13500, "respect": 8, "heist": true, "loot": "Crane's chiming cylinder", "intro": ["Lucie: A tenor who has never sung in public, who has three addresses, and who once asked me to forge a Turner. If he sings tonight, I shall eat my bonnet."], "outro": ["Théo: A brass cylinder pinned like a music box, tuned to strike one bell at one moment. Madame Viardot's clock is one of the twelve."]}, {"id": "m31", "n": 31, "fac": "apache", "chapter": 1, "title": "La Fuite du Copiste", "en": "The Copyist Flees", "brief": "Cassatt's copyist has realised he is being followed. He has taken a cab and twenty forged pastels, and is making for the Gare du Nord and the Boulogne boat.", "steps": [{"t": "steal", "vtype": "phaeton", "at": "tortoni", "text": "Take a fast phaeton outside Tortoni's."}, {"t": "race", "cps": ["tortoni", "folies", "garenord"], "time": 55, "text": "Catch the copyist's cab before the boat train goes."}, {"t": "kill", "at": "garenord", "n": 3, "armed": true, "boss": false, "text": "Crane's men are seeing him off. Deal with them."}, {"t": "collect", "at": "garenord", "n": 2, "text": "Save the portfolios from the platform."}], "reward": 12350, "respect": 8, "heist": false, "loot": "Twenty forged pastels", "intro": ["Maza: My cabmen saw him. He has a hundred-franc note in each glove and terror in his face. Bring me the pastels and him in one piece."], "outro": ["Copyist: (shaking) I only copy! I never sign! He signs them! Crane signs them, with whatever name the Baron wants!", "Maza: Then you will copy one more thing, my dear: a confession."]}, {"id": "m32", "n": 32, "fac": "crimson", "chapter": 1, "title": "Nadar", "en": "Nadar", "brief": "Nadar, photographer, balloonist and inexhaustible talker, has offered to photograph the forgeries under a raking light that shows every brushstroke. The plates must reach his studio intact.", "steps": [{"t": "goto", "at": "printers", "text": "Collect the forgeries from Lucie."}, {"t": "deliver", "at": "boulevard", "time": 0, "fragile": true, "text": "Drive the plates and the pictures to the boulevard. Glass: drive gently."}, {"t": "eaves", "at": "boulevard", "time": 20, "say": ["Nadar: Look. Under the light, a true Degas has a hundred hesitations. Your forger never hesitates. That is how you know a liar: he never stops to think.", "Nadar: I have photographed Hugo, Baudelaire, Sarah. They all hesitated. Only the forger is sure of himself."], "text": "Watch over Nadar as he works, and listen."}, {"t": "survive", "lvl": 2, "time": 20, "alarm": true, "text": "Twist: Mourier's men raid the studio for 'indecent photographs'. Hold them off while Nadar hides the plates."}], "reward": 14200, "respect": 8, "heist": true, "loot": "Nadar's photographic plates", "intro": ["Nadar: Glass, my young friend! Twenty plates of glass between you and the truth! In a balloon I once dropped one at four hundred metres and it survived. I would not count on such luck in a Paris cab."], "outro": ["Nadar: Indecent! The only indecent thing in this studio is the inspector's warrant. Here are your plates, intact. The truth, Monsieur Marchal, is chemically fixed."]}, {"id": "m33", "n": 33, "fac": "apache", "chapter": 1, "title": "Le Pont des Arts", "en": "The Pont des Arts", "brief": "Mourier has learned that Théo meets Lucie at the Institut, and has laid a trap on the Pont des Arts. Maza has learned it too, and has her own opinion of traps.", "steps": [{"t": "goto", "at": "institut", "text": "Go to the Institut de France as if you knew nothing."}, {"t": "survive", "lvl": 3, "time": 25, "alarm": true, "text": "Mourier springs the trap. Survive until Maza's porters arrive."}, {"t": "survive", "lvl": 3, "lose": true, "time": 0, "text": "In the confusion, lose the gendarmes."}, {"t": "goto", "at": "chien", "time": 140, "foot": false, "text": "Get back to Les Halles before Mourier works out where the porters came from."}], "reward": 14550, "respect": 8, "heist": true, "intro": ["Maza: He has twenty men on the bridge. I have two hundred porters at Les Halles who hate him. Arithmetic is on our side."], "outro": ["Maza: He arrested forty porters and released them all by midnight. He could not prove which ones had thrown the cabbages. I have never been prouder of a vegetable."]}, {"id": "m34", "n": 34, "fac": "crimson", "chapter": 1, "title": "Madame Morisot", "en": "Madame Morisot", "brief": "After the Pont des Arts, Mourier has every hotel and lodging-house watched. Berthe Morisot, who exhibited with the Impressionists from the first and fears nobody, has offered Théo a room in her house on the rue de Villejust, near the Étoile, for one night.", "steps": [{"t": "goto", "at": "arc", "time": 120, "foot": false, "text": "Get to the Morisots' house near the Étoile before curfew patrols begin."}, {"t": "eaves", "at": "arc", "time": 24, "say": ["Mourier: Madame, an apprentice watchmaker, a thief, has been seen in this street.", "Morisot: Inspector, I paint women in white dresses on summer afternoons. Do I look as if I harbour thieves?", "Mourier: Madame paints very modern pictures. Modern people are capable of anything.", "Morisot: Then you must arrest the century, Inspector. Good night."], "text": "Twist: Mourier himself calls at the door. Listen from the stairs."}, {"t": "tail", "at": "arc", "to": "champs", "say": ["Mourier: (to his sergeant) The Baron says leave the painters alone. I'd like to leave them in the Seine.", "Mourier: Twelve days. He wants it in twelve days."], "text": "Mourier leaves unsatisfied, and walks, not drives. Follow him down the avenue."}], "reward": 13400, "respect": 8, "heist": false, "intro": ["Morisot: My husband thinks you are a cousin from Bordeaux. Try to look provincial. No, less. Bordeaux is not the moon."], "outro": ["Morisot: (at breakfast) You followed a policeman down the Champs-Élysées in my husband's hat. I shall paint that one day, but nobody would believe it."]}, {"id": "m35", "n": 35, "fac": "avant", "chapter": 1, "title": "Durand-Ruel", "en": "Durand-Ruel", "brief": "Paul Durand-Ruel, the dealer who has risked his fortune on the Impressionists, has been offered a 'Monet' he knows Monet never painted. He will look at it only in the presence of a witness.", "steps": [{"t": "escort", "at": "durandruel", "to": "drouot", "real": true, "text": "Drive Monsieur Durand-Ruel to the Hôtel Drouot."}, {"t": "eaves", "at": "drouot", "time": 22, "say": ["Durand-Ruel: The light is wrong. Monet paints the moment before the light changes. This man has painted the moment after.", "Auctioneer: It comes with a certificate, monsieur.", "Durand-Ruel: So do bank notes. Who sold it to you?", "Auctioneer: The Vaneau collection.", "Durand-Ruel: Then the Vaneau collection had better pray."], "text": "Stand at his shoulder while he examines the canvas, and listen."}, {"t": "kill", "at": "drouot", "n": 3, "armed": true, "boss": false, "text": "Twist: the Baron's men try to take the canvas back before it can be photographed."}], "reward": 13750, "respect": 8, "heist": false, "intro": ["Durand-Ruel: Forgery is a sin, Monsieur Marchal, against the painter and against God. I am Catholic and a dealer; I find I disapprove of it twice."], "outro": ["Durand-Ruel: I shall keep this, with your permission, under lock and key. When the time comes, I will stand up in any court in France and say so."]}, {"id": "m36", "n": 36, "fac": "velvet", "chapter": 1, "title": "La Madeleine", "en": "The Madeleine", "brief": "Vaneau has invited Théo to hear Gabriel Fauré direct the choir at the Madeleine. He has also, Théo suspects, arranged to show him something in the organ loft.", "steps": [{"t": "goto", "at": "madeleine", "text": "Go to La Madeleine."}, {"t": "eaves", "at": "madeleine", "time": 22, "say": ["Fauré: (to the choir, quietly) Softer. As though you were afraid of waking someone.", "Vaneau: (to Théo) The clock in the tower is old. I mean to have it replaced, with a Vallet. Your master's. Do you see? I am putting his music in all the churches of Paris.", "Théo: Music, monsieur?", "Vaneau: Every clock is music, if you listen correctly."], "text": "Listen to the Baron during the anthem."}, {"t": "sneak", "at": "madeleine", "n": 3, "r": 9.0, "text": "After the service, slip up to the tower clock past the vergers."}, {"t": "collect", "at": "madeleine", "n": 1, "text": "Twist: Crane has already been here. Remove his cylinder from the striking train."}], "reward": 15600, "respect": 8, "heist": true, "loot": "Second chiming cylinder", "intro": ["Vaneau: Fauré is a genius, and genius is so badly paid. I have offered to buy him an organ. He refused. Imagine, a man who refuses an organ."], "outro": ["Fauré: (meeting Théo on the stair) You are the clockmaker's boy? The bell has been striking a half-tone flat for a week. Thank you. I thought I was going mad, which in a choirmaster is only a matter of time."]}, {"id": "m37", "n": 37, "fac": "apache", "chapter": 1, "title": "Le Masque", "en": "The Mask", "brief": "La Pie has been seen on the rooftops of Montmartre, carrying a bag of cylinders. This time Théo is ready for her.", "steps": [{"t": "goto", "at": "galette", "time": 90, "foot": false, "text": "Get to the Moulin de la Galette before the moon rises."}, {"t": "race", "cps": ["radet", "blutefin", "tertre", "sacrecoeur"], "time": 50, "say": ["La Pie: Still winding your legs, watchmaker?", "La Pie: You're gaining! How tiresome!"], "text": "Chase La Pie across the rooftops and the windmill yards."}, {"t": "kill", "at": "sacrecoeur", "n": 3, "armed": true, "boss": false, "text": "Twist: at the scaffolding of the Sacré-Cœur, the Baron's men are waiting for her too. They mean to silence her."}], "reward": 14450, "respect": 8, "heist": false, "intro": ["Henri: She runs the same route every night, the windmills to the Tertre. Like a cat, or a postman."], "outro": ["La Pie: (catching her breath) You fought for me. Why?", "Théo: Because I want my clock back, and you know where it is.", "La Pie: How romantic. Meet me tomorrow, under the Opéra. Come alone. Or don't come at all."]}, {"id": "m38", "n": 38, "fac": "velvet", "chapter": 1, "title": "L'Aveu", "en": "The Confession", "brief": "Under the Opéra, in the old fosse beside Garnier's reservoir, La Pie takes off her mask. Her name is Odile, and she is the Baron's ward.", "steps": [{"t": "goto", "at": "garnier", "foot": true, "text": "Go down into the cellars of the Opéra on foot."}, {"t": "sneak", "at": "garnier", "n": 4, "r": 9.0, "text": "Pass the Baron's night watchmen to the reservoir."}, {"t": "eaves", "at": "garnier", "time": 28, "say": ["Odile: He took me in when I was nine. Taught me to climb, to pick locks, to bow to duchesses. I thought it was a kind of love.", "Odile: I stole the tourbillon because he told me to. I left the feather because I wanted someone to come.", "Théo: Why me?", "Odile: Because you would come for the clock, not the money. Men who come for money can be paid to go away."], "text": "Odile is waiting. Listen to her."}, {"t": "eaves", "at": "garnier", "time": 18, "say": ["Vaneau: Odile? Are you down here, my dear? You know how I dislike it when you take the air without me.", "Odile: (whispering) Go. He must not find us together."], "text": "Twist: footsteps. The Baron himself is in the cellars. Keep listening."}, {"t": "goto", "at": "cafepaix", "time": 60, "foot": true, "text": "Get out through the artists' entrance before the Baron's watchmen return."}], "reward": 16300, "respect": 8, "heist": true, "intro": ["Théo: Garnier said there was no cellar under the Baron's box. There is. I am standing in it."], "outro": ["Théo: The Baron's ward. And the Baron's prisoner."]}, {"id": "m39", "n": 39, "fac": "apache", "chapter": 1, "title": "Les Tours de Notre-Dame", "en": "The Towers of Notre-Dame", "brief": "Mourier has found out about Odile, and has sent men to bring her in. She has fled to the one place in Paris higher than the Baron's reach: the towers of Notre-Dame.", "steps": [{"t": "goto", "at": "notredame", "time": 100, "foot": false, "text": "Get to Notre-Dame before Mourier's men climb the north tower."}, {"t": "kill", "at": "notredame", "n": 4, "armed": true, "boss": false, "text": "Fight off Mourier's men on the parvis."}, {"t": "choice", "key": "odile", "at": "notredame", "to": "hoteldieu", "ra": "Odile: You're letting me go? Then I owe you. I hate owing.", "rb": "Maza: She'll be warm, fed, and locked in. Here's for your trouble, mon petit. And don't look at me like that. Safe is safe.", "pay": [0, 1200], "text": "Odile is cornered and exhausted. Let her go free on the parvis, or march her to Maza's cab at the Hôtel-Dieu, where Maza will keep her safe and under lock."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "Lose the police across the bridges."}], "reward": 15150, "respect": 8, "heist": false, "intro": ["Maza: If the police get her, the Baron gets her. If we get her, we owe nobody anything. I like that kind of girl."], "outro": ["Théo: Spring is ending. The Salon closes. And the Baron has lost his magpie."]}, {"id": "m40", "n": 40, "fac": "avant", "chapter": 1, "title": "Fin du Printemps", "en": "The End of Spring", "brief": "The Salon has closed. The Independents have counted their losses and their friends. In the workshop on rue Mouffetard, Théo lays two brass cylinders on the bench next to his master's drawings.", "steps": [{"t": "goto", "at": "cellier", "text": "Return to the workshop on rue Mouffetard."}, {"t": "eaves", "at": "cellier", "time": 24, "say": ["Vallet: Each one strikes a single note at a single moment. Twelve notes, twelve clocks, all over Paris. Together they make a chord.", "Vallet: The chord opens the lock. But only if every clock is regulated by the same master, to the same second.", "Théo: The tourbillon.", "Vallet: Without it, the clocks drift. With it, they sing together. He needs it, and he needs twelve clocks, and he has only ten."], "text": "Listen to Vallet read the cylinders like a score."}, {"t": "collect", "at": "cellier", "n": 2, "text": "Hide the cylinders in the workshop where no thief would look: inside the broken clocks."}], "reward": 15500, "respect": 8, "heist": false, "intro": ["Vallet: Let me see them. Ah. Crane is a brute, but he is a careful brute."], "outro": ["Vallet: Summer will be long, Théo. The exiles are coming home, and the Republic means to throw itself a party. A fine time for a Baron to settle his accounts."]}, {"id": "m41", "n": 41, "fac": "avant", "chapter": 2, "title": "Monet et l'Olympia", "en": "Monet and the Olympia", "brief": "June. Claude Monet has come in from Giverny with his subscription list, to buy Manet's Olympia from the widow and give it to the nation. He receives subscribers at the Galerie Georges Petit, where he hung beside Rodin last summer, and one of Crane's men is sketching every canvas in the room.", "steps": [{"t": "goto", "at": "petit", "text": "Go to the Galerie Georges Petit on the rue de Sèze."}, {"t": "eaves", "at": "petit", "time": 22, "say": ["Visitor: What medium do you prime with, maître?", "Monet: Hope, mostly. And debt.", "Visitor: And the varnish?", "Monet: I never varnish. Varnish is for coffins.", "Monet: (to Théo, low) That one draws everything. He holds his pencil like a pickpocket."], "text": "Listen to Monet talking with a visitor who asks too many questions."}, {"t": "tail", "at": "boulevard", "to": "drouot", "say": ["Sketcher: (to himself) Ice floes, grey, rose, pale yellow. Rose? The man's mad.", "Sketcher: (to a porter at Drouot) For Mr Crane, by hand."], "text": "The sketcher leaves with a full notebook. Follow him."}, {"t": "kill", "at": "drouot", "n": 4, "armed": true, "boss": false, "text": "Twist: it is a trap. Crane knew you would follow. His men are waiting in the courtyard."}], "reward": 15850, "respect": 10, "heist": false, "intro": ["Monet: I do not paint the river, monsieur. I paint the air between me and the river. That is why nobody can copy it, they always copy the river."], "outro": ["Monet: (by letter) Thank you for the notebook. I have burnt it. It was the best drawing of my pictures that anyone has done, and therefore the most dangerous."], "card": true}, {"id": "m42", "n": 42, "fac": "velvet", "chapter": 2, "title": "Odile", "en": "Odile", "brief": "Odile has spent a month in hiding, either free on the streets or safe in Maza's cellar. Now she sends word. She knows what the twelve clocks are for, and she wants to be paid in revenge.", "steps": [{"t": "goto", "at": "bateau", "only": "odile=a", "text": "She comes to the piano works of her own accord, through the skylight."}, {"t": "eaves", "at": "bateau", "time": 22, "only": "odile=a", "say": ["Odile: You let me go. I've spent a month deciding whether that was clever or stupid.", "Odile: The vault is behind the reservoir under the Opéra. Twelve tumblers, each moved by a sound. A chord.", "Odile: He has ten clocks in place. He needs two more, and your master's tourbillon to tune them."], "text": "Listen to her."}, {"t": "goto", "at": "chien", "foot": true, "only": "odile=b", "text": "Twist: she has broken out of Maza's cellar, through the coal hole. Go to Les Halles."}, {"t": "race", "cps": ["halles", "steustache", "bank", "palaisroyal"], "time": 55, "only": "odile=b", "say": ["Odile: You locked me up! You and that cabbage-queen!", "Odile: All right! All right. I'll talk. But not in a cellar."], "text": "Chase her through the night market."}, {"t": "eaves", "at": "palaisroyal", "time": 22, "only": "odile=b", "say": ["Odile: The vault is behind the reservoir under the Opéra. Twelve tumblers, each moved by a sound.", "Odile: He has ten clocks in place. He needs two more, and your master's tourbillon to tune them.", "Odile: I'm helping you because I want him to lose. Not because I've forgiven you."], "text": "In the arcades of the Palais-Royal, she finally tells you."}], "reward": 16200, "respect": 10, "heist": false, "intro": ["Théo: Whatever we did on the towers of Notre-Dame, she is still the only person who has seen inside the Baron's vault."], "outro": ["Théo: Ten clocks in place. Two to go. And now, for the first time, La Pie is working for us."]}, {"id": "m43", "n": 43, "fac": "crimson", "chapter": 2, "title": "La Carte des Douze", "en": "The Map of the Twelve", "brief": "Odile says Crane keeps his master plan of the twelve clocks in the one place no policeman would look: the map room of the Bibliothèque nationale, filed under the wrong century.", "steps": [{"t": "goto", "at": "bnf", "text": "Go to the Bibliothèque nationale on the rue de Richelieu."}, {"t": "sneak", "at": "bnf", "n": 3, "r": 9.0, "text": "Pass the librarians and guardians into the Département des Cartes."}, {"t": "collect", "at": "bnf", "n": 3, "stealth": true, "text": "Take the three sheets of the plan from the folio of 'Paris in 1550'."}, {"t": "eaves", "at": "bnf", "time": 18, "say": ["Crane: The sheet for 1550, please.", "Librarian: Already out, monsieur. Ten minutes ago.", "Crane: Out? By whom?", "Librarian: A young man. With very clean hands. A watchmaker's hands, I'd have said."], "text": "Twist: Crane himself enters the map room. Hide and listen."}, {"t": "goto", "at": "bourse", "time": 80, "foot": true, "text": "Get out before the doors are closed."}], "reward": 18050, "respect": 10, "heist": true, "loot": "Crane's plan of the twelve clocks", "intro": ["Lucie: The Bibliothèque. Two million books and every one of them a good hiding place. Crane has a reader's card in the name of John Keats."], "outro": ["Lucie: (unrolling the sheets) Saint-Augustin, the Bourse, the Châtelet, Salle Pleyel, Salle Érard, the Madeleine, Viardot's house, the Conservatoire, the Opéra-Comique, the Sorbonne, Saint-Germain, and the Hôtel de Ville. Twelve. And all of them strike midnight together on one night only: Réveillon, at the Baron's gala."]}, {"id": "m44", "n": 44, "fac": "crimson", "chapter": 2, "title": "Le Fondeur", "en": "The Bell-Founder", "brief": "July. Jules Broca, who once cast the bells for half the churches in Paris, came home from New Caledonia with the amnesty ten years ago and has not cast a bell since. He carries trunks at the Gare de Lyon, and he does not want to be found.", "steps": [{"t": "goto", "at": "garelyon", "text": "Go to the Gare de Lyon as the Marseille express comes in."}, {"t": "eaves", "at": "garelyon", "time": 20, "say": ["Broca: Ten years home, Lucie, and I carry other men's trunks under a ceiling of iron and glass. The Tuileries are gone, the Republic is still arguing, and nobody asks me for a bell.", "Lucie: The Republic will always be arguing. That is how you know it is alive.", "Broca: And you want bells. Of course you want bells."], "text": "The platform is full of porters and holiday-makers. Find Broca and listen."}, {"t": "escort", "at": "garelyon", "to": "bastille", "real": false, "text": "Mourier's informers are on the platform. Get Broca out through the crowd to the Bastille."}, {"t": "kill", "at": "bastille", "n": 4, "armed": true, "boss": false, "text": "Twist: they have followed. Drive them off under the July Column, where Broca once stood on a barricade."}], "reward": 16900, "respect": 10, "heist": false, "intro": ["Lucie: Broca cast the bells, Théo. If anyone knows what twelve bells can do together, it's him. And he owes me his life, which is a debt I intend to collect."], "outro": ["Broca: Twelve bells tuned to a chord? It can be done. But tune one wrong, by a quarter-tone, and the chord becomes a different chord. Then whatever opens, opens to the wrong man."]}, {"id": "m45", "n": 45, "fac": "avant", "chapter": 2, "title": "Le Clocher de Saint-Augustin", "en": "The Saint-Augustin Clock", "brief": "The first of the Baron's clocks to be retuned: the tower of Saint-Augustin. Théo must get in, change Crane's cylinder for one of Broca's, and get out, without the Baron learning that anything has changed.", "steps": [{"t": "goto", "at": "staugustin", "text": "Go to Saint-Augustin."}, {"t": "goto", "at": "staugustin", "foot": true, "only": "moineau=a", "say": ["Moineau: You let me go in the winter, monsieur. I don't forget. This way, and mind your head on the coal."], "text": "Moineau is waiting by the sacristy, grinning. He has found the coal chute."}, {"t": "sneak", "at": "staugustin", "n": 4, "r": 10.0, "only": "moineau=b", "text": "No one is waiting for you. Get past the vergers and the Baron's watchmen alone."}, {"t": "collect", "at": "staugustin", "n": 1, "stealth": true, "swap": true, "text": "Swap Crane's cylinder for Broca's, without leaving a mark."}, {"t": "survive", "lvl": 1, "lose": true, "time": 0, "text": "Leave quietly."}], "reward": 18750, "respect": 10, "heist": true, "intro": ["Broca: Change the cylinder and nothing else. The Baron's man checks every clock on Sundays. If he finds a scratch, he finds you."], "outro": ["Théo: One clock is ours. Eleven to go, and a Baron who must not notice."]}, {"id": "m46", "n": 46, "fac": "apache", "chapter": 2, "title": "Le Quatorze Juillet", "en": "The Fourteenth of July", "brief": "The Fête nationale. Flags on every window, dancing in every square, and Monsieur Eiffel's tower lit from its feet to its flag above the fireworks. Mourier has chosen this night, of all nights, to move the Bourse clock's cylinder to a safer place.", "steps": [{"t": "steal", "vtype": "phaeton", "at": "republique", "text": "Take a phaeton at the Place du Château-d'Eau, under the flags."}, {"t": "tail", "at": "hoteldeville", "to": "chatelet", "say": ["Courier: (dodging dancers) Vive la République! Vive anything! Let me pass!", "Courier: (to himself) The Châtelet clock, he said, not the Bourse."], "text": "Twist: Mourier's courier is on foot among the dancers. Follow him without losing him in the crowd."}, {"t": "kill", "at": "chatelet", "n": 4, "armed": true, "boss": false, "text": "He hands the box to two armed men behind the theatre. Take it."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "Vanish into the fireworks."}], "reward": 17600, "respect": 10, "heist": false, "loot": "The Châtelet cylinder", "intro": ["Maza: Half of Paris is drunk and the other half is singing. There will never be a better night to steal from a policeman."], "outro": ["Maza: (opening the box) The Châtelet cylinder. He was moving it so you couldn't touch it, mon petit. Which means he knows someone is touching them."]}, {"id": "m47", "n": 47, "fac": "avant", "chapter": 2, "title": "La Porte de l'Enfer", "en": "The Gates of Hell", "brief": "August. Ten years after the State commissioned his great bronze door, Auguste Rodin is still at work on it at the Dépôt des Marbres, in the shadow of the Tour Eiffel, and now there is a monument to Victor Hugo to make as well. Crane wants a cast from the studio, to make a bronze 'by Rodin' of his own.", "steps": [{"t": "goto", "at": "champdemars", "text": "Go to Rodin's studio at the Dépôt des Marbres, under the Tour Eiffel."}, {"t": "eaves", "at": "champdemars", "time": 20, "say": ["Rodin: Ten years they have waited for a door to a museum that does not exist. I shall make them a door to Hell. Dante's, not the Ministry's, though I grant you the difference is small.", "Rodin: An Englishman came yesterday. He wanted a cast of my poet, the seated one, the one who thinks. I told him he could not afford to think.", "Théo: Did he leave?", "Rodin: He left a man at the gate."], "text": "Listen while Rodin works."}, {"t": "kill", "at": "champdemars", "n": 4, "armed": true, "boss": false, "text": "Twist: the man at the gate has friends, and they are coming in for the plasters."}, {"t": "deliver", "at": "cellier", "time": 0, "fragile": true, "text": "Rodin trusts you with a plaster study to hide from Crane. Drive it to the workshop as if it were alive."}], "reward": 19450, "respect": 10, "heist": true, "loot": "Rodin's plaster study", "intro": ["Rodin: (at his studio) Clay, monsieur. Clay does not lie. Bronze can be made to lie, if you pour it in the wrong mould."], "outro": ["Rodin: (by note) Keep it until the Englishman has gone to his own hell. I will need it back. It is me, in a way. All of them are."]}, {"id": "m48", "n": 48, "fac": "crimson", "chapter": 2, "title": "Les Carnets de Zola", "en": "Zola's Notebooks", "brief": "Émile Zola, whose railway novel has sold a hundred thousand copies, is documenting the markets of Paris for a novel about money. He has also, by accident, documented the Baron's concierge.", "steps": [{"t": "goto", "at": "halles", "text": "Find Monsieur Zola among the market stalls of Les Halles."}, {"t": "eaves", "at": "halles", "time": 24, "say": ["Zola: The Baron's concierge buys three kilos of meat a day for a household of two. Who eats the rest?", "Zola: She buys candles by the case, the expensive wax. Somebody works at night in that house, and not at accounts.", "Zola: And every Thursday a cab brings a man with paint on his cuffs. English. He tips badly."], "text": "Walk beside him and listen while he takes notes."}, {"t": "tail", "at": "halles", "to": "steustache", "say": ["Concierge: Three kilos of the beef. And the bones, for the Englishman's dogs.", "Concierge: (to a butcher) The master's ward is back, they say. He's in a fury about it."], "text": "The concierge is at the market now, with her basket. Follow her."}, {"t": "goto", "at": "steustache", "text": "She enters the sacristy at Saint-Eustache. A note changes hands at the poor box."}], "reward": 18300, "respect": 10, "heist": false, "loot": "Zola's notebook page", "intro": ["Zola: I write down everything, monsieur. What people eat, how they lie, what they hide in their cellars. A novelist is a policeman who has not been bribed."], "outro": ["Zola: (reading the note) 'Twelve days before Christmas, the last two clocks.' Monsieur, your Baron writes like a villain in a feuilleton. That is the one thing I cannot forgive him."]}, {"id": "m49", "n": 49, "fac": "velvet", "chapter": 2, "title": "Le Grand Livre", "en": "The Ledger", "brief": "The Baron's second ledger, the one for God, sits in the strongroom of his stockbroker by the Bourse. It records every bribe, every forgery, every policeman.", "steps": [{"t": "goto", "at": "bourse", "text": "Go to the Bourse."}, {"t": "sneak", "at": "bourse", "n": 4, "r": 10.0, "text": "Get Odile past the broker's watchmen."}, {"t": "collect", "at": "bourse", "n": 2, "stealth": true, "text": "Take the ledger and its index while Odile works the lock."}, {"t": "choice", "key": "ledger", "at": "procope", "to": "chien", "ra": "Lucie: (reading) Mourier. Three magistrates. A deputy. We print it now, Théo, while it can still frighten them.", "rb": "Maza: (weighing it in her hand) A book of debts. My favourite reading. These men will pay us to stay out of the newspapers, mon petit, for as long as we need them to.", "pay": [0, 2500], "text": "You have the ledger. Give it to Lucie at the Procope to print now, or take it to Maza at Les Halles to keep as leverage over the men named in it."}, {"t": "survive", "lvl": 3, "lose": true, "time": 0, "text": "The broker has raised the alarm. Lose the police."}], "reward": 20150, "respect": 10, "heist": true, "loot": "The Baron's second ledger", "intro": ["Odile: The broker's strongroom has a lock by Fichet. I can open it in four minutes. You will need to keep the guards occupied for five."], "outro": ["Odile: Whatever you decided to do with it, he knows it's gone. He'll be frightened now. Frightened men are careless, or very careful."]}, {"id": "m50", "n": 50, "fac": "avant", "chapter": 2, "title": "Caillebotte", "en": "Caillebotte", "brief": "Gustave Caillebotte, painter, collector, boatman and quiet patron of his friends, who lives now at Petit-Gennevilliers among his boats and roses, has offered his old rooms near the Parc Monceau as a safehouse for everything they recover.", "steps": [{"t": "escort", "at": "boulevard", "to": "monceau", "real": true, "text": "Drive Monsieur Caillebotte from the boulevard to the Parc Monceau."}, {"t": "goto", "at": "monceau", "text": "Caillebotte: These rooms. The light is north. The locks are new. And my brother is a very poor liar, so do not tell him anything."}, {"t": "sneak", "at": "monceau", "n": 3, "r": 9.0, "text": "Twist: the Baron's watchmen are already in the park. Get in without being seen."}, {"t": "collect", "at": "monceau", "n": 2, "text": "Bring in the rescued canvases from the cart."}], "reward": 20500, "respect": 10, "heist": true, "intro": ["Caillebotte: I buy my friends' pictures when nobody else will. One day the State will have to take them, if only to stop me buying more."], "outro": ["Caillebotte: You have the beginnings of a museum, Monsieur Marchal. The beginning of every museum is a theft that was put right."]}, {"id": "m51", "n": 51, "fac": "apache", "chapter": 2, "title": "Le Train de Bercy", "en": "The Bercy Train", "brief": "Crane has loaded the two remaining cylinders on a wine-train at Bercy, packed among barrels of Burgundy, to be carried to the Gare Saint-Lazare and fitted in December.", "steps": [{"t": "goto", "at": "bercy", "text": "Go to the Bercy wine stores."}, {"t": "sneak", "at": "bercy", "n": 4, "r": 10.0, "text": "Slip between the warehouses past Crane's men."}, {"t": "collect", "at": "bercy", "n": 2, "stealth": true, "text": "Take the two cylinders from the barrels."}, {"t": "destroy", "at": "bercy", "n": 2, "what": "vehicle", "vtype": "gig", "text": "Twist: Crane has a second copy of each, in two drays. Burn them both."}, {"t": "survive", "lvl": 3, "lose": true, "time": 0, "text": "The warehouse watchmen have raised the alarm. Lose the pursuit."}], "reward": 20850, "respect": 10, "heist": true, "loot": "The last two cylinders", "intro": ["Maza: Burgundy! Such a waste. Burn the wagons, keep the cylinders, and if a barrel should fall into my cart, so be it."], "outro": ["Broca: (examining them) Two cylinders, and both ours now. The Baron's chord has two notes missing. He will have to come and find them."]}, {"id": "m52", "n": 52, "fac": "crimson", "chapter": 2, "title": "L'Ombre de Mourier", "en": "Mourier's Shadow", "brief": "Lucie wants to know whom Mourier reports to, now that the ledger is gone. The only way to find out is to follow him from the Préfecture on foot.", "steps": [{"t": "tail", "at": "prefecture", "to": "hoteldeville", "say": ["Mourier: (to a flower-seller) Not today, madame.", "Mourier: (stopping dead on the bridge) ...", "Mourier: (to himself) Somebody is following me. Somebody always is."], "text": "Tail Inspector Mourier from the Préfecture. He is a policeman: he knows how to look behind him."}, {"t": "eaves", "at": "hoteldeville", "time": 22, "say": ["Crane: The ledger is gone, Inspector.", "Mourier: Then the girl is with them.", "Crane: The girl was always going to be with them. Vaneau knows it. He says let her run. She'll lead us to the apprentice and the apprentice will lead us to the cylinders.", "Mourier: And then?", "Crane: And then the Baron will want them all to disappear. Even the girl."], "text": "Among the scaffolding of the rebuilt Hôtel de Ville, he meets Crane. Listen."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "Twist: a sergent noticed you on the bridge. Lose the patrol."}], "reward": 19700, "respect": 10, "heist": false, "intro": ["Lucie: He walks to the Hôtel de Ville every evening at seven. He thinks it makes him look honest. Follow him, and keep your hat low."], "outro": ["Lucie: Even the girl. Don't tell Odile. Or rather, do. She should know who loves her."]}, {"id": "m53", "n": 53, "fac": "avant", "chapter": 2, "title": "Pissarro", "en": "Pissarro", "brief": "Camille Pissarro, in Paris for a day from Pontoise, has a pupil who wants to confess: a young painter who works for Crane and is frightened for his life.", "steps": [{"t": "goto", "at": "tanguy", "text": "Meet Pissarro at Père Tanguy's."}, {"t": "eaves", "at": "tanguy", "time": 22, "say": ["Pupil: He pays me two hundred francs for a Pissarro, maître. You sell yours for eighty.", "Pissarro: Then you are a better businessman than I am, and a worse painter.", "Pupil: The Baron wants all of us to go to London after Christmas. I don't think I'll arrive.", "Pissarro: No. Nor do I."], "text": "Listen as Pissarro and the pupil talk."}, {"t": "escort", "at": "tanguy", "to": "lorette", "real": false, "text": "Get the pupil to Lucie's friends at Notre-Dame-de-Lorette, where he can hide."}, {"t": "kill", "at": "lorette", "n": 4, "armed": true, "boss": false, "text": "Twist: Crane's men have followed. Protect the pupil."}], "reward": 20050, "respect": 10, "heist": false, "loot": "Plan of Crane's studio", "intro": ["Pissarro: The boy has talent. Talent is a terrible thing to sell. It is like selling your eyes: you get money, and then you cannot see what to buy."], "outro": ["Pupil: (to Théo) There's a studio over the Folies Bergère. That's where we paint. Twelve of us. I'll draw you the stairs."]}, {"id": "m54", "n": 54, "fac": "apache", "chapter": 2, "title": "La Fête au Tertre", "en": "The Feast at the Tertre", "brief": "Montmartre's August fête. Henri is painting portraits for a franc a head, and Crane's men have come up the hill to settle a score with the painter who hid a Monet.", "steps": [{"t": "goto", "at": "tertre", "time": 90, "foot": false, "text": "Get up the hill to the Place du Tertre."}, {"t": "hold", "at": "tertre", "time": 30, "armed": true, "text": "Hold the square with Henri's friends while the fête goes on around you."}, {"t": "kill", "at": "tertre", "n": 4, "armed": true, "boss": false, "text": "Twist: Crane's leader arrives with a revolver. Drive them off."}], "reward": 20400, "respect": 10, "heist": false, "intro": ["Henri: A franc a head! I have painted four policemen, two nuns and a donkey. The donkey had the most character."], "outro": ["Henri: (dabbing his lip) I shall paint them all from memory, and very unflattering. That is the only revenge a painter has."]}, {"id": "m55", "n": 55, "fac": "velvet", "chapter": 2, "title": "Les Horloges de la Bourse", "en": "The Bourse Clocks", "brief": "The great clock over the Bourse is the fourth of the twelve. The Baron's men check it daily. Théo will have to fit Broca's cylinder while the stockbrokers shout below.", "steps": [{"t": "goto", "at": "bourse", "text": "Go to the Bourse as the market opens."}, {"t": "sneak", "at": "bourse", "n": 4, "r": 10.0, "text": "Get past the Baron's watchmen to the clock room."}, {"t": "collect", "at": "bourse", "n": 1, "stealth": true, "swap": true, "text": "Fit Broca's cylinder in place of Crane's."}, {"t": "eaves", "at": "bourse", "time": 16, "say": ["Watchman: Clock's right, sir. Striking true.", "Crane: True to whom, I wonder. Check it again tomorrow. And the day after.", "Watchman: Sir."], "text": "Twist: someone is coming up the stair. Hide and listen."}, {"t": "survive", "lvl": 1, "lose": true, "time": 0, "text": "Leave quietly, among the brokers."}], "reward": 22250, "respect": 10, "heist": true, "intro": ["Odile: The clock room is above the trading floor. When the market opens, nobody hears anything. Not even a gunshot. Be quick."], "outro": ["Théo: Four clocks ours. Eight to go. And Crane is checking his clocks twice a day now."]}, {"id": "m56", "n": 56, "fac": "crimson", "chapter": 2, "title": "Le Châtelet", "en": "The Châtelet", "brief": "The Châtelet's clock is the fifth. The theatre is putting on a spectacular with real horses and a shipwreck, and Crane is backstage.", "steps": [{"t": "goto", "at": "chatelet", "text": "Go to the Théâtre du Châtelet."}, {"t": "sneak", "at": "chatelet", "n": 4, "r": 10.0, "text": "Cross the backstage during the shipwreck scene without being seen."}, {"t": "collect", "at": "chatelet", "n": 1, "stealth": true, "swap": true, "text": "Fit the Châtelet cylinder you took on the Fourteenth."}, {"t": "kill", "at": "chatelet", "n": 4, "armed": true, "boss": true, "text": "Twist: Crane is waiting at the stage door with his best men. Fight your way out."}], "reward": 22600, "respect": 10, "heist": true, "intro": ["Lucie: Crane is in the flies, among the ropes. He likes to watch things fall."], "outro": ["Crane: (fleeing through the crowd) Bravo, Monsieur Marchal! Encore! I shall see you at the gala! Do dress!"]}, {"id": "m57", "n": 57, "fac": "apache", "chapter": 2, "title": "Le Faux Tourbillon", "en": "The False Tourbillon", "brief": "Maza's people have heard that the tourbillon will be moved in a closed barouche from the Baron's house to the Ministry, where he has a friend. It is a chance that will never come again.", "steps": [{"t": "goto", "at": "elysee", "text": "Go to the faubourg Saint-Honoré."}, {"t": "steal", "vtype": "barouche", "at": "elysee", "text": "Take the barouche from its outriders."}, {"t": "deliver", "at": "bateau", "time": 0, "fragile": true, "text": "Drive it gently to Henri's. The tourbillon is aboard."}, {"t": "kill", "at": "bateau", "n": 4, "armed": true, "boss": false, "text": "Twist: Mourier was waiting at the piano works. He knew."}], "reward": 22950, "respect": 10, "heist": true, "intro": ["Maza: One barouche, two outriders, and a clock worth more than this whole market. Bring it back without a scratch, mon petit."], "outro": ["Henri: (opening the case) It's beautiful. It's ticking. It's... Théo, why is it ticking backwards?"]}, {"id": "m58", "n": 58, "fac": "crimson", "chapter": 2, "title": "La Fausse Pièce", "en": "The False Piece", "brief": "The tourbillon in the barouche was a copy, made by Crane to be stolen. Somebody in the crew has been talking.", "steps": [{"t": "goto", "at": "printers", "text": "Return to Lucie's."}, {"t": "eaves", "at": "printers", "time": 24, "say": ["Henri: Don't look at me. I can't keep a secret, everyone knows that, so nobody tells me any.", "Odile: You think it was me. Of course you do.", "Maza: (arriving) It was nobody. It was the concierge at the piano works. She has a son in the Sûreté.", "Lucie: Then we have all insulted each other for nothing. Good. It clears the air."], "text": "Listen while the crew argue."}, {"t": "goto", "at": "cellier", "text": "Take the copy to Vallet."}], "reward": 21800, "respect": 10, "heist": false, "loot": "Crane's copy tourbillon", "intro": ["Lucie: A copy, made to be taken. And Mourier waiting at the piano works. Somebody told him."], "outro": ["Vallet: A copy? Then he fears us. Good. And it is a very good copy, Théo, which means that Crane has had the real one in his hands for months. He has learnt it. That is worse."]}, {"id": "m59", "n": 59, "fac": "apache", "chapter": 2, "title": "Rue Mouffetard en Flammes", "en": "Rue Mouffetard in Flames", "brief": "The Baron has answered the theft of his copy in the only language he trusts. Vallet's workshop is on fire.", "steps": [{"t": "goto", "at": "cellier", "time": 80, "foot": false, "text": "Get to the workshop before the roof comes down!"}, {"t": "kill", "at": "cellier", "n": 4, "armed": true, "boss": false, "text": "The arsonists are still in the street, making sure. Drive them off."}, {"t": "escort", "at": "cellier", "to": "hoteldieu", "real": false, "text": "Get Maître Vallet to the Hôtel-Dieu."}], "reward": 22150, "respect": 10, "heist": false, "intro": ["Moineau: (running) Monsieur! Monsieur Théo! The workshop!"], "outro": ["Vallet: (in the ward) They burned the clocks. All nineteen. Never mind. I kept the drawings in my head, Théo, where nobody can set fire to them. Not even a Baron."]}, {"id": "m60", "n": 60, "fac": "avant", "chapter": 2, "title": "Fin de l'Été", "en": "The End of Summer", "brief": "The workshop is a ruin, but the drawings survive in Vallet's head, and the crew is together. Autumn is coming, and the Opéra-Comique, homeless since the fire of 1887, is rehearsing Esclarmonde at the Place du Châtelet.", "steps": [{"t": "goto", "at": "bateau", "text": "Meet the crew at the piano works."}, {"t": "eaves", "at": "bateau", "time": 24, "say": ["Lucie: Five clocks ours. Five ours, counting the Madeleine and Madame Viardot's. Seven to go: the Opéra-Comique, Pleyel, Érard, the Conservatoire, the Sorbonne, Saint-Germain and the Hôtel de Ville.", "Odile: And the master itself. The tourbillon. He keeps it in the vault, and the vault only opens when the twelve chime together.", "Broca: Then on Réveillon we ring them ourselves. Our chord, not his. And whatever opens, opens to us.", "Maza: And then we take everything inside it. I have been very patient."], "text": "Listen to the council of war."}], "reward": 22500, "respect": 10, "heist": false, "intro": ["Henri: We have five clocks, a bell-founder, a magpie, a fishwife, a forger and a watchmaker. If this were an opera it would end badly."], "outro": ["Théo: The Baron has a gala in December. So do we."]}, {"id": "m61", "n": 61, "fac": "crimson", "chapter": 3, "title": "Esclarmonde", "en": "Esclarmonde", "brief": "September. Since the Salle Favart burned in 1887, the Opéra-Comique has played in the Théâtre des Nations on the Place du Châtelet. Jules Massenet is rehearsing Esclarmonde for Mademoiselle Sanderson. The company's clock is the sixth of the twelve, and Crane has a man in the orchestra.", "steps": [{"t": "goto", "at": "lyrique", "text": "Go to the Opéra-Comique, at the Place du Châtelet."}, {"t": "eaves", "at": "lyrique", "time": 24, "say": ["Sanderson: Maître, the high G again?", "Massenet: The high G always, my child. Paris pays for the high G and forgives everything else.", "Massenet: (to the orchestra) Gentlemen, the second oboe is a rumour. Will somebody confirm him?", "Oboist: (whispering to a stagehand) The clock in the foyer. Midnight on the twenty-fourth. The Englishman will pay double."], "text": "Listen to the rehearsal, and to the second oboe, who is not playing."}, {"t": "sneak", "at": "lyrique", "n": 4, "r": 10.0, "text": "While the company rehearses, slip past the stagehands into the clock room."}, {"t": "collect", "at": "lyrique", "n": 1, "stealth": true, "swap": true, "text": "Fit Broca's cylinder in the foyer clock."}], "reward": 24350, "respect": 12, "heist": true, "intro": ["Massenet: (at the piano) Again, from the incantation. Softly, mademoiselle. You are a sorceress, not a fire-bell."], "outro": ["Massenet: (passing Théo in the corridor) You are the man who mends clocks? Then mend the critics. They are always a bar behind."], "card": true}, {"id": "m62", "n": 62, "fac": "avant", "chapter": 3, "title": "Sarah s'en va", "en": "Sarah Departs", "brief": "October. Sarah Bernhardt is rehearsing Sardou's Cléopâtre at the Porte Saint-Martin, and planning a tour of the whole world, with a company, forty trunks of costumes and a coffin she sleeps in. She needs a dresser who can climb, pick a lock and lie to customs. Odile has an idea.", "steps": [{"t": "escort", "at": "bateau", "to": "republique", "real": false, "text": "Drive Odile down from Montmartre to meet Madame Bernhardt."}, {"t": "eaves", "at": "republique", "time": 22, "say": ["Bernhardt: Can you sew?", "Odile: Badly.", "Bernhardt: Can you lie?", "Odile: Beautifully.", "Bernhardt: Then you will dress me, and lie to the newspapermen, and in Rio and Sydney and New York you will be someone else entirely. Everyone is, abroad.", "Bernhardt: But you have something to finish first. I can see it in your face. Finish it, and then come. We sail in the new year. There will be a ticket with your name on it. Your real name."], "text": "Listen to the interview."}, {"t": "kill", "at": "republique", "n": 4, "armed": true, "boss": false, "text": "Twist: the Baron's men have followed Odile. Drive them off before they reach the stage door."}], "reward": 23200, "respect": 12, "heist": false, "loot": "Bernhardt's letter of engagement", "intro": ["Odile: A dresser! For Sarah Bernhardt! In America! Théo, it's the only honest job in the world that suits a thief."], "outro": ["Odile: My real name. She said my real name. I don't think I've heard it out loud in ten years."]}, {"id": "m63", "n": 63, "fac": "apache", "chapter": 3, "title": "Les Noces de la Madeleine", "en": "The Madeleine Wedding", "brief": "October. A minister's daughter marries a banker's son at the Madeleine, and the whole of the Faubourg is on the steps. The Baron uses the crush of carriages to move the tourbillon itself.", "steps": [{"t": "goto", "at": "madeleine", "text": "Go to the Madeleine as the wedding party comes out."}, {"t": "eaves", "at": "madeleine", "time": 18, "say": ["Guest: Forty carriages, and a petrol motor from the Panhard works. It smells like a lamp.", "Other: It is the future, my dear. The future always smells.", "Fauré: (to the choir) Gently, gently. They are being married, not buried. In tempo, please."], "text": "Listen to the guests on the steps."}, {"t": "tail", "at": "madeleine", "to": "garnier", "say": ["Crane: (to himself) A wedding. A contract with flowers on it.", "Crane: (at the Opéra) Inform the Baron. Everything is ready."], "text": "Twist: Crane, in a wedding coat, walks against the crowd towards the Opéra. Follow him."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "The Baron's watchmen have seen you. Lose them."}], "reward": 23550, "respect": 12, "heist": false, "intro": ["Maza: All of Paris will be at the Madeleine. The Baron's carriage will be the only one going the other way."], "outro": ["Théo: Everything is ready. He has the tourbillon in the vault, and he believes his twelve clocks are still his. In December, we will see whose time it is."]}, {"id": "m64", "n": 64, "fac": "apache", "chapter": 3, "title": "Salle Pleyel", "en": "Salle Pleyel", "brief": "The concert hall of the piano-makers Pleyel, on the rue Rochechouart, holds the seventh clock. Ignacy Paderewski, the young Polish pianist all Paris is mad about, is giving a recital, and is in no mood to be interrupted.", "steps": [{"t": "goto", "at": "pleyel", "text": "Go to the Salle Pleyel."}, {"t": "eaves", "at": "pleyel", "time": 22, "say": ["Paderewski: The clock in this hall is three seconds fast. I can hear it from the stage. It is like playing next to a woodpecker.", "Paderewski: And some Englishman has been asking my tuner which clock strikes first in Paris. Why should a music-lover care?", "Théo: He is not a music-lover, monsieur.", "Paderewski: No. Music-lovers never ask about clocks. Only about hair."], "text": "Listen to Paderewski in the green room before he goes on."}, {"t": "sneak", "at": "pleyel", "n": 4, "r": 10.0, "text": "While he plays, get into the clock room past the Baron's men."}, {"t": "collect", "at": "pleyel", "n": 1, "stealth": true, "swap": true, "text": "Fit the cylinder."}], "reward": 25400, "respect": 12, "heist": true, "intro": ["Maza: Your pianist has the most hair and the worst temper in Paris. If you make a sound during his Beethoven, he will have you arrested and I won't pay the bail."], "outro": ["Paderewski: (after the recital) The clock is now exactly right. I noticed in the second movement. Whoever you are, you have ruined my excuse for playing badly."]}, {"id": "m65", "n": 65, "fac": "crimson", "chapter": 3, "title": "Salle Érard", "en": "Salle Érard", "brief": "The eighth clock is at the Salle Érard. Lucie's ledger, or Maza's, has made the Baron's friends nervous, and the hall is crawling with private police.", "steps": [{"t": "survive", "lvl": 3, "time": 25, "alarm": true, "only": "ledger=a", "text": "The ledger was printed, and the men it named have struck back. Mourier's men close in on the Procope. Hold out."}, {"t": "eaves", "at": "chien", "time": 18, "only": "ledger=b", "say": ["Maza: (to a frightened magistrate) Your name, page four. Your wife's name, page nine. Your mistress, page eleven. You will take your men off the Salle Érard tonight, monsieur.", "Magistrate: That is blackmail, madame.", "Maza: It's bookkeeping."], "text": "The ledger is with Maza. Listen while she uses it."}, {"t": "goto", "at": "erard", "text": "Go to the Salle Érard."}, {"t": "sneak", "at": "erard", "n": 4, "r": 10.0, "text": "Get past the private police."}, {"t": "collect", "at": "erard", "n": 1, "stealth": true, "swap": true, "text": "Fit the cylinder."}], "reward": 25750, "respect": 12, "heist": true, "intro": ["Lucie: The men in the ledger know we have it. They have hired guards for every clock in Paris."], "outro": ["Théo: Eight. Four to go, and a city that has noticed something is wrong with its clocks."]}, {"id": "m66", "n": 66, "fac": "velvet", "chapter": 3, "title": "La Demande", "en": "The Proposal", "brief": "The Baron invites Théo to dine at the Café Anglais. He has an offer to make, and a threat to make after it, and he never confuses the two.", "steps": [{"t": "goto", "at": "cafepaix", "text": "Go to the Boulevard, to dine with the Baron."}, {"t": "eaves", "at": "cafepaix", "time": 26, "say": ["Vaneau: I know about the cylinders. I know about Broca, and Lucie, and my unhappy Odile.", "Vaneau: I am going to offer you a hundred thousand francs and a workshop on the rue de la Paix. You will be the finest watchmaker in Europe.", "Théo: And my master?", "Vaneau: Your master is old. Time, Théo, is money. I simply own more of both.", "Vaneau: If you refuse, Mourier will arrest you on Christmas Eve, and Odile will be sent somewhere very far away, and very cold."], "text": "Listen to him."}, {"t": "tail", "at": "cafepaix", "to": "trinite", "say": ["Sergeant: (to a cabman) Rue de Clichy. No, wait, he's gone. Where's he gone?", "Sergeant: (to himself) The Inspector will have my stripes."], "text": "Twist: you refused. Mourier's sergeant is following you. Follow him instead, from behind."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "Lose his friends."}], "reward": 24600, "respect": 12, "heist": false, "intro": ["Vaneau: Sit, Théo. Eat. The pigeon is excellent. You look like a young man who has been climbing church towers."], "outro": ["Théo: He thinks I'm afraid of him. I am. But I'm more afraid of a world in which he owns the time."]}, {"id": "m67", "n": 67, "fac": "apache", "chapter": 3, "title": "Le Dépôt", "en": "The Dépôt", "brief": "Théo refused the Baron, and the Baron has answered. Henri has been arrested for 'insulting a magistrate' and is in the cells of the Dépôt, under the Palais de Justice.", "steps": [{"t": "goto", "at": "palaisjustice", "text": "Go to the Palais de Justice."}, {"t": "sneak", "at": "palaisjustice", "n": 5, "r": 10.0, "text": "Get past the warders of the Dépôt."}, {"t": "eaves", "at": "palaisjustice", "time": 16, "say": ["Henri: (singing, badly) Ah! que j'aime les militaires...", "Warder: Shut it, you.", "Henri: Monsieur, I am a prisoner of conscience. My conscience demands that I sing."], "text": "Find Henri's cell, and listen at the grille."}, {"t": "escort", "at": "palaisjustice", "to": "bateau", "real": false, "text": "Get Henri out through the courtyard and drive him home to Montmartre."}, {"t": "survive", "lvl": 3, "lose": true, "time": 0, "text": "Twist: the escape has been seen from the Quai des Orfèvres. Lose the gendarmes."}], "reward": 26450, "respect": 12, "heist": true, "intro": ["Maza: A painter in the Dépôt. They'll make him paint the walls. Get him out before he starts insulting the guards as well."], "outro": ["Henri: Four days in the Dépôt, and they never once let me have a pencil. I shall paint Mourier as a pig. A very accurate pig."]}, {"id": "m68", "n": 68, "fac": "avant", "chapter": 3, "title": "Rue Laffitte", "en": "Rue Laffitte", "brief": "The picture dealers of the rue Laffitte, led by Durand-Ruel, have agreed to testify against the Baron in the spring. The Baron's answer is to send men with paraffin.", "steps": [{"t": "hold", "at": "durandruel", "time": 35, "armed": true, "text": "Guard Durand-Ruel's gallery through the night."}, {"t": "kill", "at": "durandruel", "n": 5, "armed": true, "boss": false, "text": "Twist: the arsonists come in force at dawn. Drive them off."}, {"t": "destroy", "at": "lorette", "n": 2, "text": "Burn their paraffin carts before they come back."}], "reward": 25300, "respect": 12, "heist": false, "intro": ["Durand-Ruel: They want to burn my stock. Everything I own is in that gallery, monsieur. Including my debts."], "outro": ["Durand-Ruel: (at dawn, among the pictures) Every one of these is a prayer, monsieur. You have kept them from being burnt as heretics."]}, {"id": "m69", "n": 69, "fac": "crimson", "chapter": 3, "title": "Monsieur Clemenceau", "en": "Monsieur Clemenceau", "brief": "Lucie wants the story told, when it is over, by someone the Chamber cannot ignore. Georges Clemenceau, deputy, duellist and editor of La Justice, receives visitors in his house on the rue Franklin in Passy.", "steps": [{"t": "escort", "at": "procope", "to": "trocadero", "real": false, "text": "Escort Lucie to call on Monsieur Clemenceau, above the Trocadéro."}, {"t": "eaves", "at": "trocadero", "time": 26, "say": ["Clemenceau: Madame, I have fought three duels and a hundred debates. The debates were bloodier.", "Clemenceau: You ask me to print a story against a baron with friends at the Préfecture. Good. I have no friends at the Préfecture; it saves time.", "Clemenceau: Publish. The truth needs no permission, only courage. And a good printer."], "text": "Listen to Clemenceau."}, {"t": "tail", "at": "trocadero", "to": "champs", "say": ["Watcher: (to himself) The deputy's house. The Englishman will want to know.", "Watcher: (to a cab) Rue de Rivoli."], "text": "Twist: a man has been watching the house. Follow him down the avenue."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "He has called for help. Lose them."}], "reward": 25650, "respect": 12, "heist": false, "loot": "Clemenceau's letter", "intro": ["Lucie: He was mayor of Montmartre in the year of the Commune. He has seen what the powerful do when they are frightened. He will understand."], "outro": ["Clemenceau: (by note, the next day) Monsieur, I am told you followed a spy from my door. Next time bring him in. I should have liked to ask him a few questions, with the door shut."]}, {"id": "m70", "n": 70, "fac": "apache", "chapter": 3, "title": "Le Conservatoire", "en": "The Conservatoire", "brief": "The ninth clock is at the Conservatoire, in the room where the Prix de Rome is judged. Jules Massenet, who teaches composition there, knows its every eccentricity.", "steps": [{"t": "goto", "at": "conservatoire", "text": "Go to the Conservatoire."}, {"t": "eaves", "at": "conservatoire", "time": 20, "say": ["Massenet: Gentlemen, a melody is a woman. She must be flattered, then abandoned at the right moment.", "Student: And if she won't be abandoned, maître?", "Massenet: Then you have written an opera.", "Massenet: (to Théo, aside) The Englishman came. He asked me which note the clock struck. I lied, naturally. I am a composer."], "text": "Listen to Massenet in his classroom."}, {"t": "sneak", "at": "conservatoire", "n": 4, "r": 10.0, "text": "Get past the porters to the judging room."}, {"t": "collect", "at": "conservatoire", "n": 1, "stealth": true, "swap": true, "text": "Fit the cylinder."}], "reward": 27500, "respect": 12, "heist": true, "intro": ["Massenet: The clock? Charming. It strikes like a soprano who has had a little too much champagne. Why should anyone want to steal it, dear boy?"], "outro": ["Théo: Nine. Three left, and Crane knows exactly which ones."]}, {"id": "m71", "n": 71, "fac": "velvet", "chapter": 3, "title": "Le Salon de Chabrier", "en": "Chabrier's Evening", "brief": "Emmanuel Chabrier has resigned from the Ministry of the Interior to write music full time, and celebrates by giving a party for everyone he knows. One of his guests is the Baron's spy in the crew.", "steps": [{"t": "escort", "at": "batignolles", "to": "staugustin", "real": true, "text": "Drive Monsieur Chabrier to his party."}, {"t": "eaves", "at": "staugustin", "time": 24, "say": ["Chabrier: (at the piano) Ta-ra-ta-ra! You see? Bells!", "Guest: (low, to another) The bell-founder Broca is working at the foundry in Vaugirard, every night until Christmas.", "Other: The Baron will be grateful.", "Guest: The Baron is never grateful. He pays, which is better."], "text": "Listen to the guests."}, {"t": "tail", "at": "staugustin", "to": "madeleine", "say": ["Informer: (to himself) Broca, Vaugirard, every night.", "Informer: (at the Madeleine steps, to a cabman) To the Préfecture."], "text": "Twist: the informer leaves. Follow him."}, {"t": "kill", "at": "madeleine", "n": 4, "armed": true, "boss": false, "text": "Stop him before he reaches his cab."}], "reward": 26350, "respect": 12, "heist": false, "intro": ["Chabrier: You are the one with the bells? Wonderful! I have written a waltz with twelve bells in it. It sounds like a fire in a cathedral. Come in, come in, there is more wine than talent here, but only just."], "outro": ["Chabrier: (later) My spy? At my party? I am flattered. I did not think anyone took me seriously enough to spy on."]}, {"id": "m72", "n": 72, "fac": "apache", "chapter": 3, "title": "La Fonderie", "en": "The Foundry", "brief": "The informer did not get far, but Mourier has guessed. His men are going to the Vaugirard foundry where Broca is tuning the last bells.", "steps": [{"t": "goto", "at": "bonmarche", "time": 120, "foot": false, "text": "Get to Broca's foundry, behind the Bon Marché, before Mourier."}, {"t": "hold", "at": "bonmarche", "time": 30, "armed": true, "text": "Hold the foundry yard while Broca casts the last bell."}, {"t": "kill", "at": "bonmarche", "n": 5, "armed": true, "boss": true, "text": "Twist: Mourier's chief bully leads the final rush."}, {"t": "deliver", "at": "cellier", "time": 0, "fragile": true, "text": "Carry the new bell to Vallet. It is still warm, and cracks if jolted."}], "reward": 28200, "respect": 12, "heist": true, "loot": "Broca's bell", "intro": ["Broca: Let them come. I have been shot at by better policemen than Mourier, and I am still here."], "outro": ["Broca: It rings true. A quarter-tone higher than the Baron's. On Réveillon, his chord will become ours."]}, {"id": "m73", "n": 73, "fac": "crimson", "chapter": 3, "title": "La Sorbonne", "en": "The Sorbonne", "brief": "The tenth clock is in the old chapel of the Sorbonne, where the students have already noticed that it strikes thirteen.", "steps": [{"t": "goto", "at": "sorbonne", "text": "Go to the Sorbonne."}, {"t": "eaves", "at": "sorbonne", "time": 18, "say": ["Student: It struck thirteen, I tell you! Like a novel by Jules Verne!", "Other: You were drunk.", "Student: I am a student of philosophy. I am always drunk. That does not mean I cannot count."], "text": "Listen to the students arguing in the courtyard."}, {"t": "sneak", "at": "sorbonne", "n": 5, "r": 10.0, "text": "Get past the beadles and the Baron's watchmen."}, {"t": "collect", "at": "sorbonne", "n": 1, "stealth": true, "swap": true, "text": "Fit the cylinder."}], "reward": 28550, "respect": 12, "heist": true, "intro": ["Lucie: Students. They will be awake at any hour and they will notice anything. Be quick."], "outro": ["Théo: Ten. Saint-Germain, the Hôtel de Ville, and the master itself."]}, {"id": "m74", "n": 74, "fac": "avant", "chapter": 3, "title": "Saint-Germain-des-Prés", "en": "Saint-Germain-des-Prés", "brief": "The eleventh clock is in the tower of Saint-Germain-des-Prés, the oldest church in Paris. Crane has guessed it is next, and is waiting inside.", "steps": [{"t": "goto", "at": "stgermain", "text": "Go to Saint-Germain-des-Prés."}, {"t": "sneak", "at": "stgermain", "n": 5, "r": 11.0, "text": "Cross the roof and the bell-loft past Crane's men."}, {"t": "collect", "at": "stgermain", "n": 1, "stealth": true, "swap": true, "text": "Fit the cylinder."}, {"t": "kill", "at": "stgermain", "n": 5, "armed": true, "boss": true, "text": "Twist: Crane springs his trap as you leave. Fight your way out."}], "reward": 28900, "respect": 12, "heist": true, "intro": ["Odile: He's waiting for you. Let him wait. Go in through the roof, the way I would."], "outro": ["Crane: (escaping, bleeding) You've got all but one, old man. All but one. Do you know what a chord with one note missing is? It's a discord."]}, {"id": "m75", "n": 75, "fac": "velvet", "chapter": 3, "title": "Rue de Douai", "en": "The Rue de Douai", "brief": "Madame Viardot's clock was the first one Théo saved. Crane means to take it back on the night of her last Thursday of the year, and undo the chord.", "steps": [{"t": "goto", "at": "lorette", "text": "Go to Madame Viardot's."}, {"t": "eaves", "at": "lorette", "time": 20, "say": ["Viardot: (singing) Che farò senza Euridice...", "Guest: You still keep Turgenev's chair by the piano, madame?", "Viardot: Ivan sat there for thirty years. Seven years dead, and nobody else has dared to sit in it.", "Odile: (whispering) Crane's men are in the garden."], "text": "Listen to Viardot's last Thursday."}, {"t": "kill", "at": "lorette", "n": 5, "armed": true, "boss": false, "text": "Twist: Crane's men break in during the aria. Protect the house."}, {"t": "collect", "at": "lorette", "n": 1, "stealth": true, "swap": true, "text": "Fit Broca's cylinder in the clock."}], "reward": 29250, "respect": 12, "heist": true, "loot": "Viardot's clock key", "intro": ["Viardot: My clock? Again? How tiresome. Bring your watchmaker, Odile. I will sing something long and very loud."], "outro": ["Viardot: (after) They broke my window during the Gluck, which is unforgivable. But you saved the clock. Ivan would have been pleased. He liked to hear it ticking while I sang."]}, {"id": "m76", "n": 76, "fac": "crimson", "chapter": 3, "title": "Les Plans de Garnier", "en": "Garnier's Plans", "brief": "Charles Garnier does not like the Baron, and likes even less the idea that someone has built a vault under his Opéra without asking. He has the original plans of the foundations.", "steps": [{"t": "goto", "at": "institut", "text": "Meet Garnier at the Institut de France."}, {"t": "eaves", "at": "institut", "time": 22, "say": ["Garnier: Here is the reservoir. Here, the old quarry, which we filled. Or I thought we filled it.", "Garnier: If your Baron has dug into the quarry, his vault lies between the reservoir and the rue Scribe. A good place to hide gold. A bad place to be caught: there is only one way out.", "Théo: Two. Through the sewer.", "Garnier: Monsieur, no gentleman leaves my Opéra through the sewer.", "Théo: I am not a gentleman."], "text": "Listen to him over the plans."}, {"t": "collect", "at": "institut", "n": 2, "text": "Copy the two sheets of the foundation plans."}, {"t": "survive", "lvl": 1, "lose": true, "time": 0, "text": "Leave quietly."}], "reward": 28100, "respect": 12, "heist": false, "loot": "Garnier's foundation plans", "intro": ["Garnier: A vault? Under my house? Without my permission? Monsieur, I would rather have a Baron in my bed."], "outro": ["Garnier: (calling after) If you find anything of mine down there, bring it back! I want to know who has been stealing my marble!"]}, {"id": "m77", "n": 77, "fac": "avant", "chapter": 3, "title": "L'Omnibus", "en": "The Omnibus", "brief": "The crew will need a getaway vehicle large enough for eleven people and a vault's worth of paintings. Maza has her eye on a Madeleine–Bastille omnibus.", "steps": [{"t": "steal", "vtype": "omnibus", "at": "madeleine", "text": "Take the omnibus at the Madeleine."}, {"t": "race", "cps": ["vendome", "palaisroyal", "hoteldeville", "bastille"], "time": 80, "text": "Drive the whole route to the Bastille as if nothing were wrong. Make every stop."}, {"t": "deliver", "at": "chien", "time": 0, "text": "Bring it to Les Halles to be hidden under the cabbages."}], "reward": 28450, "respect": 12, "heist": false, "loot": "The getaway omnibus", "intro": ["Maza: Twenty-six seats, three horses and a conductor who owes me money. Nobody looks twice at an omnibus."], "outro": ["Maza: (patting a horse) This one is Cléopâtre. She bites policemen. We shall get on very well."]}, {"id": "m78", "n": 78, "fac": "apache", "chapter": 3, "title": "Le Masque de Crane", "en": "Crane's Mask", "brief": "Crane has gone to ground in the studio above the Folies Bergère, where his twelve painters work. The pupil's plan of the stairs is good. Maza wants to raid it before he can move.", "steps": [{"t": "goto", "at": "folies", "text": "Go to the Folies Bergère."}, {"t": "sneak", "at": "folies", "n": 5, "r": 11.0, "text": "Climb the back stairs past Crane's watchmen."}, {"t": "collect", "at": "folies", "n": 3, "stealth": true, "text": "Take three canvases that are proof of the forgery: half-finished, with Crane's notes on them."}, {"t": "kill", "at": "folies", "n": 5, "armed": true, "boss": false, "text": "Twist: Crane's men discover the raid. Get the painters out."}], "reward": 30300, "respect": 12, "heist": true, "loot": "Crane's unfinished forgeries", "intro": ["Lucie: Twelve painters. Some of them are prisoners, and some are thieves. Try to tell the difference before you hit anyone."], "outro": ["Pupil: (outside) He's gone. He was gone before you came. He left a note: 'Until Réveillon, old man.'"]}, {"id": "m79", "n": 79, "fac": "velvet", "chapter": 3, "title": "Les Préparatifs", "en": "The Preparations", "brief": "November. The gala is in six weeks. The crew gathers in Caillebotte's rooms by the Parc Monceau to set the plan.", "steps": [{"t": "goto", "at": "monceau", "text": "Go to the safehouse by the Parc Monceau."}, {"t": "eaves", "at": "monceau", "time": 28, "say": ["Lucie: Twelve clocks. Twelve of our friends at twelve clocks, each with a watch set by Théo. At midnight they strike our chord.", "Broca: The vault opens to our tuning, not his.", "Odile: I'll be in the Baron's box, with him. He likes me there.", "Maza: The omnibus waits in the rue Scribe.", "Théo: And Mourier will be at the Opéra to arrest me at midnight.", "Henri: Then we make him late."], "text": "Listen to the plan."}, {"t": "collect", "at": "monceau", "n": 3, "text": "Collect the pocket watches, each set to the same second, to hand out."}], "reward": 29150, "respect": 12, "heist": false, "intro": ["Maza: Everyone gets paid. Even heroes. Especially heroes, they're the most expensive."], "outro": ["Henri: Everything we have, on one night. If it fails, I want it known that I always said it would."]}, {"id": "m80", "n": 80, "fac": "avant", "chapter": 3, "title": "Fin de l'Automne", "en": "The End of Autumn", "brief": "The first snow. Vallet, out of hospital, is living in a room behind Henri's piano works. He asks to see Théo's watch, the one he will carry on the night.", "steps": [{"t": "goto", "at": "bateau", "text": "Go to Vallet's room behind the piano works."}, {"t": "eaves", "at": "bateau", "time": 22, "say": ["Vallet: When I was your age, I thought time was a thing one measured. It is not. It is a thing one keeps, like a promise.", "Vallet: The Baron thinks he can own it. He cannot. The best he can do is borrow it, and he has borrowed too much.", "Vallet: Go, Théo. Keep your promise."], "text": "Listen to your master."}], "reward": 29500, "respect": 12, "heist": false, "intro": ["Vallet: Show me. Ah. You have made it yourself. That is good. One should only trust one's own work on the night that matters."], "outro": ["Théo: The last night of autumn. And in December, a gala."]}, {"id": "m81", "n": 81, "fac": "crimson", "chapter": 4, "title": "La Neige", "en": "The Snow", "brief": "December. Snow on the boulevards and the gas-lamps haloed in it. Mourier has put a price of five thousand francs on Théo's head, and every informer in Paris can count.", "steps": [{"t": "survive", "lvl": 4, "time": 30, "alarm": true, "text": "Mourier's manhunt sweeps the Latin Quarter. Survive it."}, {"t": "survive", "lvl": 4, "lose": true, "time": 0, "text": "Lose them in the snow."}, {"t": "goto", "at": "procope", "time": 120, "foot": true, "text": "Regroup at the Procope, on foot, by the back streets."}], "reward": 31350, "respect": 14, "heist": true, "intro": ["Lucie: Five thousand francs. I'm almost insulted. In 1871 they offered ten for me."], "outro": ["Lucie: (pouring) Twenty days. Then either we are heroes, or we are in New Caledonia. I have been to Geneva; I should like to see somewhere warm."], "card": true}, {"id": "m82", "n": 82, "fac": "avant", "chapter": 4, "title": "L'Hôtel de Ville", "en": "The Hôtel de Ville", "brief": "The twelfth clock stands in the rebuilt Hôtel de Ville, still half in scaffolding. Crane has posted his best men there, because it is the last.", "steps": [{"t": "goto", "at": "hoteldeville", "text": "Go to the Hôtel de Ville."}, {"t": "sneak", "at": "hoteldeville", "n": 5, "r": 12.0, "text": "Climb the scaffolding past Crane's watchmen."}, {"t": "collect", "at": "hoteldeville", "n": 1, "stealth": true, "swap": true, "text": "Fit the twelfth cylinder."}, {"t": "eaves", "at": "hoteldeville", "time": 16, "say": ["Foreman: Clock's checked, Mr Crane. All twelve true.", "Crane: All twelve true? Then why do I feel as if someone has been through my pockets?", "Foreman: Nerves, sir.", "Crane: I don't have nerves. I have instincts. Double the watch."], "text": "Twist: Crane's foreman is on the scaffold. Listen."}, {"t": "goto", "at": "stjacques", "time": 60, "foot": true, "text": "Get down and away to the Tour Saint-Jacques before the watch is doubled."}], "reward": 31700, "respect": 14, "heist": true, "intro": ["Odile: Scaffolding! Oh, I love scaffolding. It's like a ladder that's been told a secret."], "outro": ["Théo: Twelve. Every clock in the Baron's chord is now tuned to ours."]}, {"id": "m83", "n": 83, "fac": "avant", "chapter": 4, "title": "Les Invitations", "en": "The Invitations", "brief": "The crew needs invitations to the gala, and costumes to wear under them. Lucie can forge the cards; the costumes must come from the Opéra-Comique's wardrobe.", "steps": [{"t": "collect", "at": "palaisroyal", "n": 4, "text": "Collect the paper, ink, seals and ribbon around the Palais-Royal."}, {"t": "goto", "at": "printers", "text": "Bring them to Lucie."}, {"t": "goto", "at": "favart", "foot": true, "text": "Go to the Salle Favart on foot."}, {"t": "sneak", "at": "favart", "n": 5, "r": 11.0, "text": "Get past the wardrobe mistresses and the night porter."}, {"t": "collect", "at": "favart", "n": 3, "stealth": true, "text": "Take three musicians' costumes unseen."}], "reward": 32050, "respect": 14, "heist": true, "loot": "Forged gala invitations", "intro": ["Lucie: Paper from the Palais-Royal, ink from the rue de Rivoli, seals from a man who owes me. Then the costumes. Musicians: nobody ever looks at musicians."], "outro": ["Lucie: (holding a card to the lamp) 'The Baron Vaneau requests the pleasure.' He will have the pleasure. I shall see to it personally."]}, {"id": "m84", "n": 84, "fac": "velvet", "chapter": 4, "title": "La Répétition Générale", "en": "The Dress Rehearsal", "brief": "The Baron's gala rehearsal at the Opéra. As his clockmaker, Théo is expected to wind the great clock in the Baron's box. He means to set it, very carefully, wrong.", "steps": [{"t": "goto", "at": "garnier", "text": "Go to the Opéra."}, {"t": "eaves", "at": "garnier", "time": 22, "say": ["Vaneau: You came back to me, my dear.", "Odile: Where else would I go?", "Vaneau: Nowhere. That is the beauty of it. On Réveillon you will sit beside me and watch the door open, and then we shall go to London, you and I, and be very rich and very bored.", "Odile: I can hardly wait."], "text": "While you work, listen to the Baron and Odile in the box."}, {"t": "collect", "at": "garnier", "n": 1, "stealth": true, "swap": true, "text": "Swap the master escapement for your own, set twelve seconds slow."}, {"t": "goto", "at": "bateau", "text": "Report to the crew."}], "reward": 32400, "respect": 14, "heist": true, "intro": ["Vaneau: Wind it well, Théo. On Réveillon, at midnight, this clock will be the most important in Paris."], "outro": ["Théo: Twelve seconds. When his clock strikes midnight, ours will already have struck. The door will open to our chord, and he will be twelve seconds too late."]}, {"id": "m85", "n": 85, "fac": "crimson", "chapter": 4, "title": "Les Douze Sonneurs", "en": "The Twelve Ringers", "brief": "Twelve friends at twelve clocks, each with one of Théo's watches. They must all have them by tonight, and Mourier is watching the streets.", "steps": [{"t": "steal", "vtype": "phaeton", "at": "procope", "text": "Take a phaeton at the Procope."}, {"t": "race", "cps": ["stgermain", "sorbonne", "chatelet", "hoteldeville", "bourse", "favart", "conservatoire", "lorette", "staugustin", "madeleine"], "time": 120, "text": "Deliver the watches to all ten outlying clocks before the night watch begins."}, {"t": "kill", "at": "pleyel", "n": 4, "armed": true, "boss": false, "text": "Twist: Crane's men are guarding the Pleyel clock. Clear them for your ringer."}, {"t": "kill", "at": "erard", "n": 4, "armed": true, "boss": false, "text": "And the Érard."}], "reward": 31250, "respect": 14, "heist": false, "intro": ["Broca: Twelve of the best: three bell-ringers, two students, a nun, a cab driver, five old Communards who came home with the amnesty. They'll ring true, I promise you."], "outro": ["Théo: Twelve watches, twelve ringers, one second. If this works, the whole of Paris will strike midnight together, and only we will know why."]}, {"id": "m86", "n": 86, "fac": "apache", "chapter": 4, "title": "Le Fiacre de Mourier", "en": "Mourier's Cab", "brief": "On Réveillon, Mourier will ride to the Opéra at a quarter to midnight to arrest Théo in front of the whole of Paris. Make him late.", "steps": [{"t": "goto", "at": "prefecture", "text": "Go to the Préfecture."}, {"t": "sneak", "at": "prefecture", "n": 4, "r": 11.0, "text": "Get into the stable yard past the night watch."}, {"t": "destroy", "at": "prefecture", "n": 3, "what": "vehicle", "vtype": "brougham", "text": "Wreck Mourier's three carriages."}, {"t": "survive", "lvl": 3, "lose": true, "time": 0, "text": "Lose the gendarmes."}], "reward": 33100, "respect": 14, "heist": true, "intro": ["Maza: Wreck his carriages. Gently, if you can; I want the horses for myself."], "outro": ["Maza: (later) He will have to walk to the Opéra. At his weight, through the snow, that is three quarters of an hour. Exactly enough."]}, {"id": "m87", "n": 87, "fac": "avant", "chapter": 4, "title": "La Galerie Secrète", "en": "The Secret Gallery", "brief": "Durand-Ruel and Caillebotte will receive everything recovered from the vault and authenticate it before witnesses, so that nothing can be taken back.", "steps": [{"t": "escort", "at": "durandruel", "to": "monceau", "real": true, "text": "Drive Monsieur Durand-Ruel to the safehouse by the Parc Monceau."}, {"t": "eaves", "at": "monceau", "time": 18, "say": ["Caillebotte: My brother thinks we are mad.", "Durand-Ruel: Your brother is a philatelist. All philatelists think everyone else is mad.", "Caillebotte: (to Théo) We will be waiting, all night, with the lamps lit."], "text": "Listen to Durand-Ruel and Caillebotte."}], "reward": 31950, "respect": 14, "heist": false, "intro": ["Durand-Ruel: Everything will go back to its painter, or to its rightful owner. You have my word. Which, I am told, is worth more than my credit."], "bonus": {"at": "monceau", "pay": 1200, "text": "Caillebotte has left a gift for the crew in the coach house: a purse for the night."}, "outro": ["Théo: Everything is ready. Except me."]}, {"id": "m88", "n": 88, "fac": "velvet", "chapter": 4, "title": "Le Gala", "en": "The Gala", "brief": "Réveillon at the Opéra. Everyone who matters in Paris is here, in jewels and furs, and so, in musicians' coats, is the crew.", "steps": [{"t": "goto", "at": "garnier", "text": "Arrive at the gala."}, {"t": "sneak", "at": "garnier", "n": 6, "r": 12.0, "text": "Pass the Baron's guards on the grand staircase and the corridors."}, {"t": "eaves", "at": "garnier", "time": 24, "say": ["Vaneau: To time, ladies and gentlemen, which belongs to me!", "Guest: To the Baron!", "Vaneau: (to Théo, as he passes) You came, my clockmaker. Mourier will be here at midnight. I asked him to wait until after the champagne.", "Odile: (low) Eleven minutes, Théo."], "text": "In the Baron's box, Vaneau raises a glass. Listen."}, {"t": "goto", "at": "garnier", "foot": true, "text": "Slip away from the box down to the cellars."}], "reward": 33800, "respect": 14, "heist": true, "intro": ["Henri: (in a borrowed tailcoat) I look like a waiter at a funeral. Perfect."], "outro": ["Théo: Eleven minutes to midnight. Twelve clocks set. One door."]}, {"id": "m89", "n": 89, "fac": "crimson", "chapter": 4, "title": "Minuit", "en": "Midnight", "brief": "The bells ring across Paris, twelve clocks striking one chord, twelve seconds before the Baron's. Under the Opéra, the vault begins to open.", "steps": [{"t": "hold", "at": "garnier", "time": 35, "armed": true, "text": "Hold the cellar door while the chimes play."}, {"t": "kill", "at": "garnier", "n": 5, "armed": true, "boss": false, "text": "Twist: the Baron's cellar guards heard the chord too. Drive them off the door."}, {"t": "goto", "at": "garnier", "foot": true, "text": "Enter the vault."}], "reward": 32650, "respect": 14, "heist": false, "intro": ["Broca: (in Théo's ear, from memory) Listen. There. Saint-Augustin. The Bourse. The Châtelet. Now. Now!"], "outro": ["Théo: The door is open. Twelve seconds before his. For twelve seconds, the Baron's vault belongs to us."]}, {"id": "m90", "n": 90, "fac": "apache", "chapter": 4, "title": "Le Coffre", "en": "The Vault", "brief": "Inside: paintings, manuscripts, instruments, ledgers, bonds, and on a velvet cushion, ticking, the tourbillon of Augustin Vallet.", "steps": [{"t": "collect", "at": "garnier", "n": 5, "text": "Gather the treasures: the paintings, the scores, the violin, the ledgers, and the tourbillon!"}, {"t": "survive", "lvl": 4, "time": 35, "alarm": true, "text": "Twist: the Baron's clock strikes twelve seconds late, and the Baron knows. His guards flood the cellars."}], "reward": 34500, "respect": 14, "heist": true, "loot": "The Vallet tourbillon", "intro": ["Maza: (whispering) Mother of God. I have been a receiver of stolen goods for thirty years, and I have never seen so many in one room."], "outro": ["Théo: (lifting it) It's still keeping perfect time. Of course it is."]}, {"id": "m91", "n": 91, "fac": "avant", "chapter": 4, "title": "L'Évasion", "en": "The Escape", "brief": "Out through the sewer, up through a grating on the rue Scribe, into a waiting omnibus with a horse called Cléopâtre.", "steps": [{"t": "steal", "vtype": "omnibus", "at": "garnier", "text": "Take the getaway omnibus."}, {"t": "deliver", "at": "monceau", "time": 0, "fragile": true, "text": "Drive to the safehouse. Priceless cargo, so drive gently!"}, {"t": "survive", "lvl": 4, "lose": true, "time": 0, "text": "Twist: Mourier has arrived on foot, furious, and called out the army. Lose the pursuit."}], "reward": 34850, "respect": 14, "heist": true, "intro": ["Maza: Cléopâtre! Go!"], "outro": ["Caillebotte: (at the door) Come in, come in. Lamps are lit. Durand-Ruel has his ledger open. Everything will be written down, monsieur. Everything."]}, {"id": "m92", "n": 92, "fac": "crimson", "chapter": 4, "title": "Le Faussaire", "en": "The Forger", "brief": "Silas Crane has fled for the Gare du Nord with a case of masterpieces and a ticket on the boat train.", "steps": [{"t": "steal", "vtype": "phaeton", "at": "garenord", "text": "Take a phaeton."}, {"t": "race", "cps": ["garenord", "gareest", "republique"], "time": 55, "text": "Catch Crane's cab."}, {"t": "kill", "at": "gareest", "n": 6, "armed": true, "boss": true, "text": "Take down Crane and his men."}], "reward": 33700, "respect": 14, "heist": false, "loot": "Crane's portfolio", "intro": ["Lucie: He'll be in London by breakfast if we let him. I don't want him in London. I want him in a cell, with no paint."], "outro": ["Crane: (on the ground) Well played, old man. Do you know, I always wanted to paint something of my own? Never had the time.", "Lucie: You'll have years now."]}, {"id": "m93", "n": 93, "fac": "apache", "chapter": 4, "title": "L'Inspecteur", "en": "The Inspector", "brief": "Mourier has barricaded himself in the Préfecture, burning his own ledgers in the grate.", "steps": [{"t": "goto", "at": "prefecture", "text": "Go to the Préfecture."}, {"t": "kill", "at": "prefecture", "n": 6, "armed": true, "boss": true, "text": "Face Mourier's loyalists."}, {"t": "collect", "at": "prefecture", "n": 3, "text": "Save the unburnt ledger pages."}, {"t": "choice", "key": "mourier", "at": "palaisjustice", "to": "procope", "ra": "Magistrate: The Republic thanks you, monsieur. Discreetly. The Republic is always discreet about its policemen.", "rb": "Lucie: Front page. His face, his ledger, his wife's champagne. Let the magistrates try to be discreet about that.", "pay": null, "text": "Mourier is in your hands. Deliver him and his ledger to the examining magistrate at the Palais de Justice, or to Lucie's newspaper at the Procope, where all of Paris will read it by morning."}], "reward": 34050, "respect": 14, "heist": false, "loot": "Mourier's last ledger", "intro": ["Maza: He's burning the evidence. Policemen do that. It's called experience."], "outro": ["Mourier: (as they take him) You think you've won, boy? Barons always come back.", "Théo: So do watchmakers. We're very patient."]}, {"id": "m94", "n": 94, "fac": "velvet", "chapter": 4, "title": "Le Baron", "en": "The Baron", "brief": "Vaneau has fled to his private train at the Batignolles yards. He has taken Odile with him.", "steps": [{"t": "race", "cps": ["garnier", "gare", "railyard"], "time": 70, "text": "Race the Baron to the Batignolles yards!"}, {"t": "kill", "at": "railyard", "n": 6, "armed": true, "boss": true, "text": "Defeat Vaneau's bodyguard."}, {"t": "escort", "at": "railyard", "to": "monceau", "real": false, "text": "Bring Odile to safety."}], "reward": 34400, "respect": 14, "heist": false, "intro": ["Henri: He's taken Odile. To his train. Théo, run!"], "outro": ["Vaneau: (in handcuffs, on the snow) Time, Théo. It still belongs to somebody.", "Théo: Yes, monsieur. To everyone. That's the point."]}, {"id": "m95", "n": 95, "fac": "avant", "chapter": 4, "title": "Le Retour du Tourbillon", "en": "The Return of the Tourbillon", "brief": "The tourbillon goes home, to a room behind a piano works in Montmartre, where an old man is waiting with his loupe.", "steps": [{"t": "deliver", "at": "bateau", "time": 0, "fragile": true, "text": "Drive the tourbillon to Maître Vallet. Gently."}, {"t": "eaves", "at": "bateau", "time": 20, "say": ["Vallet: Ah. There you are.", "Vallet: It keeps perfect time. Of course it does. Time is the one thing they could never steal from us.", "Vallet: Théo, it is yours now. No. Don't argue. I made it to open a door. You made it open the right one."], "text": "Watch your master open the case."}], "reward": 36250, "respect": 14, "heist": true, "intro": ["Henri: Gently. You've carried it through a sewer and a war. Don't drop it now."], "outro": ["Théo: (to himself) I'll keep it. I'll keep it like a promise."]}, {"id": "m96", "n": 96, "fac": "crimson", "chapter": 4, "title": "La Une", "en": "The Front Page", "brief": "The whole story, printed. Lucie has run off ten thousand copies and wants them on every café table in Paris by breakfast.", "steps": [{"t": "goto", "at": "palaisjustice", "only": "mourier=a", "say": ["Magistrate: The Baron, Crane and Mourier will all stand trial in the spring. The Republic will be very thorough, and very quiet."], "text": "First, the examining magistrate wants a statement. Go to the Palais de Justice."}, {"t": "goto", "at": "procope", "only": "mourier=b", "say": ["Lucie: Every paper in Paris has picked it up. The magistrates had to act by noon. They hated it. I've never been happier."], "text": "The Procope is besieged by journalists. Lucie's front page has done its work."}, {"t": "collect", "at": "boulmich", "n": 4, "text": "Hand out the papers on the Boulevard Saint-Michel."}, {"t": "goto", "at": "procope", "text": "Toast at the Procope."}], "reward": 35100, "respect": 14, "heist": false, "intro": ["Lucie: The truth needs no permission. Clemenceau said so. Only courage, and a good printer."], "outro": ["Lucie: 'L'Affaire du Tourbillon', the headline. I wanted 'The Watchmaker's Revenge', but Clemenceau said it was vulgar, and he should know."]}, {"id": "m97", "n": 97, "fac": "apache", "chapter": 4, "title": "Les Comptes", "en": "Settling Accounts", "brief": "Maza settles the crew's accounts. Everyone gets paid; the stolen art goes home.", "steps": [{"t": "goto", "at": "chien", "fence": 2000, "text": "Collect your share."}, {"t": "escort", "at": "chien", "to": "monceau", "real": false, "text": "Drive Maza to see the safehouse gallery."}], "reward": 35450, "respect": 14, "heist": false, "intro": ["Maza: I've been through every franc. Everyone gets paid, mon petit. Even heroes. Even me. Especially me."], "outro": ["Maza: (looking at the pictures) So this is what all the fuss was about. Paint. I could have sold them all, you know. I'm glad I didn't. Don't tell anyone."]}, {"id": "m98", "n": 98, "fac": "avant", "chapter": 4, "title": "Les Indépendants", "en": "The Independents", "brief": "Degas, Cassatt, Morisot, Pissarro and young Signac come to Caillebotte's to see the recovered works before they go home to their owners.", "steps": [{"t": "goto", "at": "monceau", "text": "Go to the safehouse gallery."}, {"t": "eaves", "at": "monceau", "time": 22, "say": ["Pissarro: Look, there are three of mine. I didn't know anyone had ever wanted to steal me.", "Morisot: It is the best review you have ever had, Camille.", "Degas: So the watchmaker's boy has better taste than the Baron. Unsurprising. Barons buy names. Watchmakers buy works.", "Signac: Monsieur Degas, you have just said something kind.", "Degas: (to Théo) You will come to dinner on Friday. As a guest. And with no opinions."], "text": "Listen to the painters among the pictures."}], "reward": 35800, "respect": 14, "heist": false, "intro": ["Cassatt: I said you were to be believed. Nobody listened. They never listen to Americans, or to women. I am both, so I have twice the satisfaction."], "outro": ["Théo: No opinions, Monsieur Degas. Only the time."]}, {"id": "m99", "n": 99, "fac": "velvet", "chapter": 4, "title": "Odile", "en": "Odile", "brief": "Odile leaves Paris as herself at last. The boat train leaves from Saint-Lazare, and Madame Bernhardt's company, bound around the world, is waiting for its new dresser.", "steps": [{"t": "escort", "at": "monceau", "to": "gare", "real": false, "text": "Drive Odile to the Gare Saint-Lazare."}, {"t": "eaves", "at": "gare", "time": 20, "say": ["Odile: I'll write. Badly. Every week.", "Théo: Write me the time in Rio, and New York, and Sydney. I want to set a clock to it.", "Odile: Wind your clocks, Théo. And when you hear one strike midnight, think of a thief."], "text": "On the platform. Listen."}], "reward": 36150, "respect": 14, "heist": false, "loot": "Odile's feather", "intro": ["Odile: Don't make a scene, Théo. I'm a professional, I can't be seen weeping on a platform."], "outro": ["Théo: (as the train leaves) Odile Vaneau, dresser to Sarah Bernhardt. It suits her. She was always in costume."]}, {"id": "m100", "n": 100, "fac": "avant", "chapter": 4, "title": "Réveillon", "en": "New Year's Eve", "brief": "The last night of 1890. Midnight in a room behind a piano works in Montmartre, where the tourbillon is going to strike twelve.", "steps": [{"t": "escort", "at": "bateau", "to": "tertre", "real": false, "text": "Bring Henri and Vallet up to the Place du Tertre."}, {"t": "hold", "at": "tertre", "time": 15, "armed": true, "text": "Watch the fireworks over Paris as the clocks strike midnight."}], "reward": 36500, "respect": 14, "heist": false, "loot": "Henri's portrait of the apprentice", "intro": ["Henri: Champagne! Real champagne, Maza swears it fell off a cart! Théo, come up, the whole of Paris is going to strike midnight!"], "outro": ["Vallet: Listen. All of them, together. Saint-Augustin, the Bourse, Notre-Dame. And ours.", "Théo: Happy New Year, Maître.", "Vallet: Happy New Year, Théo. Keep good time."]}, {"id": "s101", "n": 101, "fac": "side", "chapter": -1, "title": "Courses de Fiacres", "en": "Cab Races", "brief": "The cabmen of the Right Bank race at night for a purse of fifty francs and the honour of their horses.", "steps": [{"t": "steal", "vtype": "brougham", "at": "boulevard", "text": "Take a cab on the Boulevard des Italiens."}, {"t": "race", "cps": ["boulevard", "bourse", "halles", "chatelet"], "time": 65, "text": "Hit the checkpoints before the old cabman."}], "reward": 2000, "respect": 0, "intro": ["Old cabman: My mare has won nine races and lost one, and the one she lost she was asleep. Beat her if you can, young man."]}, {"id": "s102", "n": 102, "fac": "side", "chapter": -1, "title": "Le Receleur de Nuit", "en": "Night Fence", "brief": "At night Les Halles fills with loose goods: crates fallen from carts, baskets nobody claims. Maza buys it all.", "steps": [{"t": "collect", "at": "halles", "n": 4, "text": "Collect the loose goods."}, {"t": "goto", "at": "chien", "fence": 600, "text": "Sell them to Maza."}], "reward": 2400, "respect": 0, "intro": ["Maza: Whatever's loose is mine, mon petit. Whatever's fastened is someone else's. Learn the difference."]}, {"id": "s103", "n": 103, "fac": "side", "chapter": -1, "title": "L'Accordeur", "en": "The Piano Tuner", "brief": "A concert grand must reach the Salle Pleyel without a scratch for Paderewski's recital.", "steps": [{"t": "steal", "vtype": "gig", "at": "bateau", "text": "Take the piano cart."}, {"t": "deliver", "at": "pleyel", "time": 0, "fragile": true, "text": "Deliver it to Salle Pleyel. Fragile!"}], "reward": 2800, "respect": 0, "intro": ["Henri: If you scratch it, Paderewski will hear it from the stage. He hears everything. He hears things that haven't happened yet."]}, {"id": "s104", "n": 104, "fac": "side", "chapter": -1, "title": "Les Copistes", "en": "The Copyists", "brief": "Crane buys copies from art students at the Louvre. Swap theirs for blank canvases before he collects.", "steps": [{"t": "goto", "at": "louvre", "text": "Go to the Louvre."}, {"t": "sneak", "at": "louvre", "n": 3, "r": 9.0, "text": "Pass the guardians of the Grande Galerie."}, {"t": "collect", "at": "louvre", "n": 3, "stealth": true, "text": "Swap three copies unseen."}], "reward": 3200, "respect": 0, "intro": ["Lucie: Swap three. Don't feel sorry for the students, they'll paint better copies next week."]}, {"id": "s105", "n": 105, "fac": "side", "chapter": -1, "title": "L'Omnibus", "en": "The Omnibus", "brief": "Run the Madeleine–Bastille omnibus line, stopping at every stop, and keep the passengers happy.", "steps": [{"t": "steal", "vtype": "omnibus", "at": "madeleine", "text": "Take the omnibus."}, {"t": "race", "cps": ["madeleine", "vendome", "palaisroyal", "hoteldeville", "bastille"], "time": 90, "text": "Make all the stops!"}], "reward": 3600, "respect": 0, "intro": ["Conductor: Twenty-six seats, and every one of them complains."]}, {"id": "s106", "n": 106, "fac": "side", "chapter": -1, "title": "Les Apaches de Belleville", "en": "The Belleville Toughs", "brief": "A gang of extortionists is squeezing the small shops of Belleville in the Baron's name.", "steps": [{"t": "kill", "at": "belleville", "n": 4, "armed": true, "boss": false, "text": "Drive them off."}], "reward": 4000, "respect": 0, "intro": ["Shopkeeper: They want ten francs a week, monsieur, for protection. From whom? From them."]}, {"id": "s107", "n": 107, "fac": "side", "chapter": -1, "title": "Le Pickpocket", "en": "The Pickpocket", "brief": "A pickpocket is working the Châtelet crowds. Follow him back to the man he works for.", "steps": [{"t": "tail", "at": "chatelet", "to": "hoteldeville", "say": ["Pickpocket: (to himself) Three watches, one purse, a handkerchief. A good evening."], "text": "Tail the pickpocket."}, {"t": "kill", "at": "hoteldeville", "n": 3, "armed": false, "boss": false, "text": "He hands his takings to two bruisers. Take back the watches."}], "reward": 4400, "respect": 0, "intro": ["Henri: The thin one in the brown coat. He has had three watches in ten minutes."]}, {"id": "s108", "n": 108, "fac": "side", "chapter": -1, "title": "Les Moulins", "en": "The Windmills", "brief": "A rooftop race across the Montmartre windmills, for a bet with Henri's friends.", "steps": [{"t": "race", "cps": ["galette", "radet", "blutefin", "tertre"], "time": 55, "text": "Race the windmills!"}], "reward": 4800, "respect": 0, "intro": ["Henri: Ten francs says you can't do it in under a minute. I don't have ten francs, but it's the principle."]}, {"id": "s109", "n": 109, "fac": "side", "chapter": -1, "title": "L'Alarme", "en": "The Alarm", "brief": "The Banque de France wants its new alarm tested by someone who knows how to run.", "steps": [{"t": "goto", "at": "bank", "text": "Go to the Banque de France."}, {"t": "survive", "lvl": 2, "time": 25, "alarm": true, "text": "Survive the alarm drill."}, {"t": "survive", "lvl": 2, "lose": true, "time": 0, "text": "Lose the police."}], "reward": 5200, "respect": 0, "intro": ["Bank official: You will run, monsieur, and we shall see whether our alarm can catch you. It is all very scientific."]}, {"id": "s110", "n": 110, "fac": "side", "chapter": -1, "title": "Les Partitions", "en": "Sheet Music", "brief": "Deliver the Conservatoire's orchestral parts to the publishers before tomorrow's concerts.", "steps": [{"t": "collect", "at": "conservatoire", "n": 3, "text": "Collect the scores."}, {"t": "goto", "at": "durand", "text": "Deliver to Durand et Schoenewerk."}, {"t": "goto", "at": "heugel", "text": "And to Heugel's, Au Ménestrel."}], "reward": 5600, "respect": 0, "intro": ["Copyist: Durand first, then Heugel. If they arrive in the wrong order, they will both complain to Massenet, and Massenet will be charming about it, which is worse."]}, {"id": "s111", "n": 111, "fac": "side", "chapter": -1, "title": "Le Cirque", "en": "The Circus", "brief": "Escort a horse-trainer and her prize mare from the Abbesses to the Cirque Fernando before the evening show.", "steps": [{"t": "escort", "at": "abbesses", "to": "fernando", "real": false, "text": "Bring the trainer to the Cirque Fernando."}], "reward": 6000, "respect": 0, "intro": ["Trainer: She is called Duchesse, and she does not like cabs, policemen or men with moustaches."], "outro": ["Lautrec: (from the front row, sketching) Mademoiselle Duchesse has better legs than the whole corps de ballet. Do not tell the corps de ballet."]}, {"id": "s112", "n": 112, "fac": "side", "chapter": -1, "title": "La Tour de Monsieur Eiffel", "en": "Monsieur Eiffel's Tower", "brief": "Gustave Eiffel keeps a laboratory at the top of his tower. A case of barometers from the Richard works must reach it before the weather turns.", "steps": [{"t": "steal", "vtype": "gig", "at": "bastille", "text": "Take the instrument-maker's gig."}, {"t": "deliver", "at": "eiffel", "time": 0, "fragile": true, "text": "Deliver the barometers to the foot of the Tour Eiffel. Fragile!"}, {"t": "goto", "at": "eiffel", "foot": true, "text": "Carry the case in under the great arch."}], "reward": 6400, "respect": 0, "intro": ["Eiffel: The instruments, monsieur, and intact. Up there the wind tells the truth, and I mean to hear every word."], "outro": ["Eiffel: Three hundred metres of iron, and every newspaper in Paris said it would fall down. It is the newspapers, monsieur, that keep falling down."]}, {"id": "s113", "n": 113, "fac": "side", "chapter": -1, "title": "Les Gymnopédies", "en": "The Gymnopédies", "brief": "Erik Satie, second pianist at the Chat Noir, has had his satchel of manuscripts snatched on the rue de Laval.", "steps": [{"t": "goto", "at": "chatnoir", "text": "Go to the Chat Noir."}, {"t": "eaves", "at": "chatnoir", "time": 16, "say": ["Salis: Messieurs, you are in the most literary cabaret in the world. Kindly pay as if you knew it.", "Customer: The thief went towards the Galette, with the pianist's bag.", "Satie: My bag. With my umbrella in it."], "text": "Listen to Salis and his customers."}, {"t": "kill", "at": "galette", "n": 3, "armed": false, "boss": false, "text": "The snatch-thieves are drinking at the Moulin de la Galette. Take back the satchel."}, {"t": "goto", "at": "chatnoir", "text": "Return it to the Chat Noir."}], "reward": 6800, "respect": 0, "intro": ["Satie: They took my music, monsieur. Slow music. The thief will be very disappointed."], "outro": ["Satie: Thank you. I shall dedicate something to you. Something very slow, so that you have time to enjoy it."]}, {"id": "s114", "n": 114, "fac": "side", "chapter": -1, "title": "La Tour Saint-Jacques", "en": "The Tour Saint-Jacques", "brief": "The Belleville toughs want the square at the Tour Saint-Jacques for their Sunday game. The market women want it more.", "steps": [{"t": "hold", "at": "stjacques", "time": 25, "armed": true, "text": "Hold the square."}], "reward": 7200, "respect": 0, "intro": ["Market woman: You keep them off for half an hour, and we'll keep you in onions till Easter."]}];
